/* Déclic — Notions fondamentales : analyse (4) — exponentielle et logarithme de base a, limite d’une fonction, asymptotes et suites, la dérivée */
(()=>{
/* ---------- helpers locaux ---------- */
const x='<i>x</i>', n='<i>n</i>', h='<i>h</i>';
// Blocs de théorie : chaque argument devient un paragraphe (sauf s’il commence déjà par <p>, <ul> ou <ol>)
const B=(c,...ps)=>`<div class="blk ${c}">${ps.map(s=>/^<(ul|ol|p)[ >]/.test(s)?s:`<p>${s}</p>`).join('')}</div>`;
const DEF=(...p)=>B('def',...p), THM=(...p)=>B('thm',...p), PROP=(...p)=>B('prop',...p), IDEA=(...p)=>B('idea',...p), WHY=(...p)=>B('why',...p), EX=(...p)=>B('ex',...p), WARN=(...p)=>B('warn',...p), KEEP=(...p)=>B('keep',...p);
const RAP=(...p)=>`<div class="blk" data-t="Rappel">${p.map(s=>`<p>${s}</p>`).join('')}</div>`;
const L=(a,v='x')=>`lim<sub>${v}→${a}</sub>`;
const lg=(a,s)=>`log<sub>${a}</sub> ${s}`;
const pw=(a,e)=>`${a}<sup>${e}</sup>`;
const tab=(head,rows)=>`<table style="border-collapse:collapse;margin:6px auto"><tr>${head.map(c=>`<th style="border-bottom:2px solid var(--line);padding:4px 9px">${c}</th>`).join('')}</tr>${rows.map(r=>`<tr>${r.map(c=>`<td style="padding:4px 9px;text-align:center;border-bottom:1px solid var(--line)">${c}</td>`).join('')}</tr>`).join('')}</table>`;
// Point creux (valeur exclue) sur un repère P ; r en unités du repère
const hole=(P,cx,cy,r,c='var(--accent)')=>P.circ(cx,cy,r,{c,w:2,fill:'var(--surface)',fo:1});
const sg=t=>t>0?1:t<0?-1:0;

COURS.push(
/* ===================== 1. EXPONENTIELLE ET LOGARITHME DE BASE a ===================== */
{subj:'gred',sem:'ana',id:'gred-exp-log-def',h:'Exponentielle et logarithme de base a',p:'Donner un sens à 2^√2, construire la fonction exponentielle de base a sur tout ℝ, puis sa réciproque le logarithme : règles de calcul, graphes, équations et inéquations.',steps:[
  {h:'Que veut dire 2^√2 ?',p:`<p>Tu sais calculer 2³ = 8, 2⁻¹ = 1/2 et 2<sup>3/2</sup> = (√2)³ = 2√2. Mais que vaut <b>2<sup>√2</sup></b> ? L’exposant √2 n’est pas une fraction : on ne peut ni « multiplier 2 par lui-même √2 fois », ni prendre une racine. Pour l’instant, 2<sup>√2</sup> n’a <b>aucun sens</b>.</p>`
   +RAP(`Pour <i>a</i> &gt; 0 et <i>r</i> = <i>p</i>/<i>q</i> rationnel, <i>a</i><sup><i>r</i></sup> = (<sup><i>q</i></sup>√<i>a</i>)<sup><i>p</i></sup>. Sur ℚ, les règles <i>a</i><sup><i>r</i>+<i>s</i></sup> = <i>a</i><sup><i>r</i></sup><i>a</i><sup><i>s</i></sup> et (<i>a</i><sup><i>r</i></sup>)<sup><i>s</i></sup> = <i>a</i><sup><i>rs</i></sup> sont vraies, et <i>r</i> ↦ <i>a</i><sup><i>r</i></sup> est croissante quand <i>a</i> &gt; 1.`)
   +IDEA(`√2 = 1,41421… est coincé entre des rationnels : 1,4 &lt; √2 &lt; 1,5, puis 1,41 &lt; √2 &lt; 1,42, et ainsi de suite. Comme <i>r</i> ↦ 2<sup><i>r</i></sup> est croissante sur ℚ, le nombre cherché devrait être coincé de la même façon : 2<sup>1,4</sup> &lt; 2<sup>√2</sup> &lt; 2<sup>1,5</sup>, puis 2<sup>1,41</sup> &lt; 2<sup>√2</sup> &lt; 2<sup>1,42</sup>… Déplace le curseur : l’encadrement des exposants se resserre, et l’encadrement des valeurs aussi. Il semble ne rester qu’un seul nombre possible, proche de 2,665.`),
   params:[{id:'k',l:'Décimales de √2 utilisées',min:0,max:6,v:0}],
   draw:v=>{ const p=10**v.k, r=Math.floor(Math.SQRT2*p)/p, s=r+1/p, P=plane({x:[0,10],y:[0,3.2],h:150,grid:false,axes:false});
     const ex=t=>1+8*(t-1), vx=t=>1+8*(2**t-2)/2;
     P.arrow(0.5,2.3,9.7,2.3,{c:'var(--muted)',w:1.5,hs:8}).arrow(0.5,0.7,9.7,0.7,{c:'var(--muted)',w:1.5,hs:8});
     P.text(0.5,2.3,'exposants',{dy:-10,c:'var(--muted)',s:11}).text(0.5,0.7,'valeurs 2ʳ',{dy:-10,c:'var(--muted)',s:11});
     [1,2].forEach(t=>P.seg(ex(t),2.15,ex(t),2.45,{c:'var(--muted)',w:1.5}).text(ex(t),2.3,String(t),{a:'middle',dy:22,c:'var(--muted)',s:11}));
     [2,3,4].forEach(t=>P.seg(vx(t),0.55,vx(t),0.85,{c:'var(--muted)',w:1.5}).text(vx(t),0.7,String(t),{a:'middle',dy:22,c:'var(--muted)',s:11}));
     P.seg(ex(r),2.3,ex(s),2.3,{c:'var(--accent)',w:6}).seg(vx(r),0.7,vx(s),0.7,{c:'var(--spark)',w:6});
     P.seg(ex(r),2.3,vx(r),0.7,{c:'var(--line)',w:1,dash:true}).seg(ex(s),2.3,vx(s),0.7,{c:'var(--line)',w:1,dash:true});
     P.dot(ex(Math.SQRT2),2.3,{r:4,c:'var(--ink)',l:'√2',dy:-10}).dot(vx(2**Math.SQRT2),0.7,{r:4,c:'var(--ink)',l:'2^√2 ?',dy:-10});
     return P.svg(); },
   info:v=>{ const p=10**v.k, r=Math.floor(Math.SQRT2*p)/p, s=r+1/p; return `${fmt(r,v.k)} ≤ √2 ≤ ${fmt(s,v.k)} donne ${fmt(2**r,4)} ≤ 2<sup>√2</sup> ≤ ${fmt(2**s,4)}. Largeur de l’encadrement : ${fmt(2**s-2**r,4)}.`; },
   note:'Le tableau de valeurs suggère un nombre, il ne le définit pas. L’étape suivante donne la définition rigoureuse.'},
  {h:'Définir a^x pour x réel',p:`<p>On veut définir <i>a</i><sup><i>x</i></sup> pour <b>tout</b> réel <i>x</i>, de façon que les valeurs rationnelles déjà connues restent les mêmes et que la fonction reste croissante. La borne supérieure, qui existe dans ℝ pour tout ensemble non vide majoré, fournit exactement l’outil.</p>`
   +DEF(`Soit <i>a</i> &gt; 1 et <i>x</i> ∈ ℝ. On pose <b><i>a</i><sup><i>x</i></sup> = sup { <i>a</i><sup><i>r</i></sup> : <i>r</i> ∈ ℚ, <i>r</i> ≤ <i>x</i> }</b>. Si 0 &lt; <i>a</i> &lt; 1, on pose <i>a</i><sup><i>x</i></sup> = (1/<i>a</i>)<sup>−<i>x</i></sup>, et 1<sup><i>x</i></sup> = 1.`)
   +WHY(`L’ensemble est non vide (il y a des rationnels plus petits que <i>x</i>) et majoré : si <i>s</i> est un rationnel plus grand que <i>x</i>, tout <i>a</i><sup><i>r</i></sup> de l’ensemble vérifie <i>a</i><sup><i>r</i></sup> ≤ <i>a</i><sup><i>s</i></sup> par croissance sur ℚ. La borne supérieure existe donc. Si <i>x</i> est lui-même rationnel, le plus grand élément de l’ensemble est <i>a</i><sup><i>x</i></sup> : la nouvelle définition redonne l’ancienne valeur.`)
   +IDEA(`<i>a</i><sup><i>x</i></sup> est le nombre vers lequel se resserrent les encadrements <i>a</i><sup><i>r</i></sup> ≤ <i>a</i><sup><i>x</i></sup> ≤ <i>a</i><sup><i>s</i></sup> avec <i>r</i> ≤ <i>x</i> ≤ <i>s</i> rationnels. Ces encadrements se resserrent vraiment : <i>a</i><sup><i>s</i></sup> − <i>a</i><sup><i>r</i></sup> = <i>a</i><sup><i>r</i></sup>(<i>a</i><sup><i>s</i>−<i>r</i></sup> − 1), et <i>a</i><sup>1/<i>n</i></sup> → 1 quand <i>n</i> → ∞. C’est ce qui rend la fonction obtenue continue.`)
   +EX(`2<sup>√2</sup> = sup { 2<sup><i>r</i></sup> : <i>r</i> ≤ √2 } ≈ 2,6651. Et (1/2)<sup>√2</sup> = 2<sup>−√2</sup> = 1/2<sup>√2</sup> ≈ 0,3752.`),
   note:'Pour a < 0, on ne définit pas a^x : (−8)^(1/3) = −2 mais (−8)^(2/6) demanderait la racine sixième de 64, qui vaut 2. Les règles de calcul casseraient. Les bases sont toujours strictement positives.'},
  {h:'Les règles de calcul restent vraies',p:`<p>Une définition par borne supérieure est peu commode pour calculer. Heureusement, les règles connues sur ℚ passent à tous les réels.</p>`
   +PROP(`Pour <i>a</i>, <i>b</i> &gt; 0 et <i>x</i>, <i>y</i> réels :<ul><li><b><i>a</i><sup><i>x</i>+<i>y</i></sup> = <i>a</i><sup><i>x</i></sup> · <i>a</i><sup><i>y</i></sup></b> et <i>a</i><sup>−<i>x</i></sup> = 1/<i>a</i><sup><i>x</i></sup> ;</li><li><b>(<i>a</i><sup><i>x</i></sup>)<sup><i>y</i></sup> = <i>a</i><sup><i>xy</i></sup></b> ;</li><li>(<i>ab</i>)<sup><i>x</i></sup> = <i>a</i><sup><i>x</i></sup><i>b</i><sup><i>x</i></sup> ;</li><li><i>a</i><sup>0</sup> = 1, <i>a</i><sup>1</sup> = <i>a</i>, et <i>a</i><sup><i>x</i></sup> &gt; 0 toujours.</li></ul>`)
   +WHY(`Prenons la première. Encadrons <i>x</i> et <i>y</i> par des rationnels : <i>r</i> ≤ <i>x</i> ≤ <i>r</i>′ et <i>s</i> ≤ <i>y</i> ≤ <i>s</i>′. Alors <i>a</i><sup><i>r</i></sup><i>a</i><sup><i>s</i></sup> = <i>a</i><sup><i>r</i>+<i>s</i></sup> ≤ <i>a</i><sup><i>x</i>+<i>y</i></sup> ≤ <i>a</i><sup><i>r</i>′+<i>s</i>′</sup> = <i>a</i><sup><i>r</i>′</sup><i>a</i><sup><i>s</i>′</sup>, et le produit <i>a</i><sup><i>x</i></sup><i>a</i><sup><i>y</i></sup> est coincé entre les mêmes bornes. Quand les encadrements se resserrent, les deux nombres coincés sont forcés d’être égaux. Les autres règles se démontrent de la même manière.`)
   +EX(`3<sup>√2</sup> · 3<sup>2−√2</sup> = 3<sup>√2+2−√2</sup> = 3² = 9. &nbsp; (2<sup>√2</sup>)<sup>√2</sup> = 2<sup>√2·√2</sup> = 2² = 4. &nbsp; 10<sup>−0,5</sup> = 1/√10.`)
   +WARN(`<i>a</i><sup><i>x</i></sup> · <i>a</i><sup><i>y</i></sup> n’est pas <i>a</i><sup><i>xy</i></sup>, et <i>a</i><sup><i>x</i></sup> + <i>a</i><sup><i>y</i></sup> ne se simplifie pas. Teste toujours avec de petits entiers : 2² · 2³ = 32 = 2⁵, pas 2⁶.`)},
  {h:'Calcule avec les règles',p:`Que vaut ${F('(5<sup>√3</sup>)<sup>√3</sup>','5')} ?`,lab:'valeur =',ans:25,
   why:'(5^√3)^√3 = 5^(√3·√3) = 5³ = 125, puis 125/5 = 25.'},
  {h:'La fonction exponentielle de base a',p:`<p>Fixons la base <i>a</i> &gt; 0 et faisons varier l’exposant : on obtient une fonction définie sur tout ℝ.</p>`
   +DEF(`La <b>fonction exponentielle de base <i>a</i></b> est exp<sub><i>a</i></sub> : ℝ → ]0 ; +∞[, <i>x</i> ↦ <i>a</i><sup><i>x</i></sup>.`)
   +PROP(`exp<sub><i>a</i></sub> est continue sur ℝ, passe par (0 ; 1) et (1 ; <i>a</i>), et :<ul><li>si <i>a</i> &gt; 1, elle est <b>strictement croissante</b> ;</li><li>si 0 &lt; <i>a</i> &lt; 1, elle est <b>strictement décroissante</b> ;</li><li>si <i>a</i> = 1, elle est constante égale à 1.</li></ul>Pour <i>a</i> ≠ 1, elle prend chaque valeur de ]0 ; +∞[ exactement une fois.`)
   +WHY(`Pour <i>a</i> &gt; 1 et <i>x</i> &lt; <i>y</i> : <i>a</i><sup><i>y</i></sup> − <i>a</i><sup><i>x</i></sup> = <i>a</i><sup><i>x</i></sup>(<i>a</i><sup><i>y</i>−<i>x</i></sup> − 1). Or <i>y</i> − <i>x</i> &gt; 0 dépasse un rationnel <i>r</i> &gt; 0, donc <i>a</i><sup><i>y</i>−<i>x</i></sup> ≥ <i>a</i><sup><i>r</i></sup> &gt; 1 : la différence est positive. Pour 0 &lt; <i>a</i> &lt; 1, <i>a</i><sup><i>x</i></sup> = (1/<i>a</i>)<sup>−<i>x</i></sup> renverse le sens. Les valeurs prises : <i>a</i><sup><i>n</i></sup> ≥ 1 + <i>n</i>(<i>a</i> − 1) dépasse tout nombre, <i>a</i><sup>−<i>n</i></sup> = 1/<i>a</i><sup><i>n</i></sup> descend sous tout nombre positif, et la continuité (valeurs intermédiaires) remplit tout ]0 ; +∞[.`)
   +IDEA(`Déplace la base. Pour <i>a</i> &gt; 1, la courbe s’écrase sur l’axe des <i>x</i> à gauche et grimpe d’autant plus vite que <i>a</i> est grand. Pour <i>a</i> &lt; 1, c’est l’image miroir : <i>a</i><sup><i>x</i></sup> = (1/<i>a</i>)<sup>−<i>x</i></sup>. Toutes les courbes passent par (0 ; 1).`),
   params:[{id:'a',l:'Base a',min:.25,max:4,step:.25,v:2}],
   draw:v=>{ const P=plane({x:[-3.5,3.5],y:[-.6,8],h:300,lab:1}); P.fn(t=>v.a**t); if(v.a!==1) P.fn(t=>(1/v.a)**t,{c:'var(--muted)',w:1.5,dash:true});
     P.dot(0,1,{r:5,c:'var(--ink)',l:'(0 ; 1)'}).dot(1,v.a,{r:5,c:'var(--spark)',l:'(1 ; a)'}); return P.svg(); },
   info:v=>`<i>a</i> = ${fmt(v.a)} : exp<sub>a</sub> est ${v.a>1?'strictement croissante':v.a<1?'strictement décroissante':'constante'}. ${v.a!==1?`En pointillé, la base 1/<i>a</i> = ${fmt(1/v.a,3)} : la courbe symétrique.`:''} a<sup>2</sup> = ${fmt(v.a**2,3)}, a<sup>−1</sup> = ${fmt(1/v.a,3)}.`,
   note:'On dit aussi « la fonction x ↦ aˣ ». Le nombre e, la base la plus naturelle, viendra plus loin : ici la base est un réel positif quelconque.'},
  {kind:'Pratique',h:'Trouve la base',p:'La courbe de <i>x</i> ↦ <i>a</i><sup><i>x</i></sup> passe par le point marqué (2 ; 6,25). Règle la base <i>a</i> pour que la courbe passe par ce point.',
   params:[{id:'a',l:'Base a',min:.5,max:4,step:.25,v:2}],
   draw:v=>{ const P=plane({x:[-2.5,3.5],y:[-.6,9],h:300,lab:1}); P.fn(t=>v.a**t).dot(2,6.25,{r:6,c:'var(--spark)',l:'(2 ; 6,25)'}).dot(2,v.a**2,{r:4,c:'var(--ink)'}); return P.svg(); },
   info:v=>`a² = ${fmt(v.a**2,4)}`,
   ok:v=>v.a===2.5,
   why:'Il faut a² = 6,25 avec a > 0, donc a = √6,25 = 2,5. Comme exp_a prend chaque valeur une seule fois, c’est la seule base possible.'},
  {h:'Le logarithme de base a',p:`<p>Pour <i>a</i> ≠ 1, chaque <i>y</i> &gt; 0 est atteint par un seul exposant : l’équation <i>a</i><sup><i>x</i></sup> = <i>y</i> a exactement une solution. On lui donne un nom.</p>`
   +DEF(`Soit <i>a</i> &gt; 0, <i>a</i> ≠ 1, et <i>y</i> &gt; 0. Le <b>logarithme de base <i>a</i></b> de <i>y</i>, noté <b>log<sub><i>a</i></sub> <i>y</i></b>, est l’unique réel <i>x</i> tel que <i>a</i><sup><i>x</i></sup> = <i>y</i> : <b><i>a</i><sup><i>x</i></sup> = <i>y</i> ⇔ <i>x</i> = log<sub><i>a</i></sub> <i>y</i></b>. La fonction log<sub><i>a</i></sub> : ]0 ; +∞[ → ℝ est la <b>réciproque</b> de exp<sub><i>a</i></sub>.`)
   +IDEA(`log<sub><i>a</i></sub> <i>y</i> répond à la question « quel exposant faut-il donner à <i>a</i> pour obtenir <i>y</i> ? ». Les deux fonctions se défont l’une l’autre : <i>a</i><sup>log<sub><i>a</i></sub> <i>y</i></sup> = <i>y</i> et log<sub><i>a</i></sub>(<i>a</i><sup><i>x</i></sup>) = <i>x</i>. Leurs graphes sont symétriques par rapport à la droite <i>y</i> = <i>x</i> (figure, base 2).`)
   +EX(`log<sub>2</sub> 8 = 3 car 2³ = 8. &nbsp; log<sub>10</sub> 0,001 = −3 car 10<sup>−3</sup> = 0,001. &nbsp; log<sub>1/2</sub> 4 = −2 car (1/2)<sup>−2</sup> = 4. &nbsp; log<sub>5</sub> √5 = 1/2. Toujours : log<sub><i>a</i></sub> 1 = 0 et log<sub><i>a</i></sub> <i>a</i> = 1.`)
   +PROP(`log<sub><i>a</i></sub> a le même sens de variation que exp<sub><i>a</i></sub> : strictement croissante si <i>a</i> &gt; 1, décroissante si <i>a</i> &lt; 1. Elle est continue, et prend toutes les valeurs réelles.`)
   +WARN(`log<sub><i>a</i></sub> 0 et log<sub><i>a</i></sub>(−3) n’existent pas : <i>a</i><sup><i>x</i></sup> est toujours strictement positif, donc aucun exposant ne donne 0 ni un nombre négatif.`),
   fig:(()=>{ const P=plane({x:[-3,6],y:[-3,6],h:300,lab:1}); P.fn(t=>t,{c:'var(--muted)',w:1.5,dash:true}).fn(t=>2**t).fn(t=>Math.log2(t),{from:.02,c:'var(--spark)'});
     P.text(2.2,5,'y = 2ˣ',{c:'var(--accent)'}).text(4.2,1.4,'y = log₂ x',{c:'var(--spark)'}).dot(1,2,{r:4,c:'var(--accent)'}).dot(2,1,{r:4,c:'var(--spark)'}).dot(0,1,{r:4,c:'var(--accent)'}).dot(1,0,{r:4,c:'var(--spark)'}); return P.svg(); })(),
   note:'Dans le graphe, le point (1 ; 2) de l’exponentielle devient le point (2 ; 1) du logarithme : on échange abscisse et ordonnée.'},
  {h:'Un logarithme à calculer',p:`Que vaut ${lg(3,'(1/81)')} ?`,lab:'log₃(1/81) =',ans:-4,
   why:'81 = 3⁴, donc 1/81 = 3⁻⁴. L’exposant à donner à 3 pour obtenir 1/81 est −4.'},
  {h:'Les propriétés du logarithme',p:`<p>Chaque règle de l’exponentielle se traduit en une règle du logarithme. Le logarithme <b>transforme les produits en sommes</b> : c’est pour cela qu’il a été inventé, avant les calculatrices.</p>`
   +PROP(`Pour <i>a</i> &gt; 0, <i>a</i> ≠ 1, <i>x</i>, <i>y</i> &gt; 0 et <i>r</i> réel :<ul><li><b>log<sub><i>a</i></sub>(<i>xy</i>) = log<sub><i>a</i></sub> <i>x</i> + log<sub><i>a</i></sub> <i>y</i></b> ;</li><li>log<sub><i>a</i></sub>(<i>x</i>/<i>y</i>) = log<sub><i>a</i></sub> <i>x</i> − log<sub><i>a</i></sub> <i>y</i>, en particulier log<sub><i>a</i></sub>(1/<i>y</i>) = −log<sub><i>a</i></sub> <i>y</i> ;</li><li><b>log<sub><i>a</i></sub>(<i>x</i><sup><i>r</i></sup>) = <i>r</i> log<sub><i>a</i></sub> <i>x</i></b>, par exemple log<sub><i>a</i></sub> √<i>x</i> = ½ log<sub><i>a</i></sub> <i>x</i>.</li></ul>`)
   +WHY(`Posons <i>u</i> = log<sub><i>a</i></sub> <i>x</i> et <i>v</i> = log<sub><i>a</i></sub> <i>y</i>, c’est-à-dire <i>a</i><sup><i>u</i></sup> = <i>x</i> et <i>a</i><sup><i>v</i></sup> = <i>y</i>. Alors <i>a</i><sup><i>u</i>+<i>v</i></sup> = <i>a</i><sup><i>u</i></sup><i>a</i><sup><i>v</i></sup> = <i>xy</i>. Donc <i>u</i> + <i>v</i> est <b>un</b> exposant qui donne <i>xy</i> ; comme il n’y en a qu’un, c’est log<sub><i>a</i></sub>(<i>xy</i>). Même raisonnement pour la puissance : (<i>a</i><sup><i>u</i></sup>)<sup><i>r</i></sup> = <i>a</i><sup><i>ru</i></sup> = <i>x</i><sup><i>r</i></sup>, donc log<sub><i>a</i></sub>(<i>x</i><sup><i>r</i></sup>) = <i>ru</i>. Le quotient s’en déduit avec <i>r</i> = −1.`)
   +EX(`log<sub>2</sub>(8 · 32) = log<sub>2</sub> 8 + log<sub>2</sub> 32 = 3 + 5 = 8. Vérification : 8 · 32 = 256 = 2⁸. &nbsp; log<sub>10</sub>(10<sup>7</sup>/100) = 7 − 2 = 5. &nbsp; log<sub>3</sub>(√27) = ½ · 3 = 3/2.`)
   +WARN(`log<sub><i>a</i></sub>(<i>x</i> + <i>y</i>) ne se simplifie pas : log<sub>2</sub>(4 + 4) = 3 alors que log<sub>2</sub> 4 + log<sub>2</sub> 4 = 4. Et (log<sub><i>a</i></sub> <i>x</i>)<sup><i>r</i></sup> n’est pas <i>r</i> log<sub><i>a</i></sub> <i>x</i>.`)},
  {kind:'Méthode',h:'Simplifier une expression avec des logarithmes',
   p:'<b>Quand :</b> une somme ou une différence de logarithmes de même base, avec des coefficients. <b>Pourquoi ça marche :</b> on lit les propriétés à l’envers : <i>r</i> log<sub><i>a</i></sub> <i>x</i> devient log<sub><i>a</i></sub>(<i>x</i><sup><i>r</i></sup>), une somme devient le logarithme d’un produit, une différence celui d’un quotient. À la fin, on reconnaît une puissance de la base. <b>Comment :</b><ol><li>rentre chaque coefficient en exposant ;</li><li>regroupe en un seul logarithme (produit pour +, quotient pour −) ;</li><li>écris l’argument comme une puissance de <i>a</i>, et lis l’exposant.</li></ol>',
   demo:{enonce:`Simplifier 2 ${lg(3,'6')} − ${lg(3,'4')}.`,
    etapes:[{f:`2 ${lg(3,'6')} = ${lg(3,'(6²)')} = ${lg(3,'36')}`,w:'Le coefficient 2 rentre en exposant : r log x = log(xʳ).'},
     {f:`${lg(3,'36')} − ${lg(3,'4')} = ${lg(3,'(36/4)')} = ${lg(3,'9')}`,w:'Une différence de logarithmes est le logarithme du quotient.'},
     {f:`9 = 3², donc ${lg(3,'9')} = 2`,w:'On reconnaît une puissance de la base 3.'}],
    conclusion:`2 ${lg(3,'6')} − ${lg(3,'4')} = 2.`},
   note:'Si l’argument final n’est pas une puissance évidente de la base, décompose-le en facteurs premiers : 72 = 2³ · 3², donc log₆ 72 = log₆(6² · 2) = 2 + log₆ 2.'},
  {h:'Regroupe',p:`Que vaut ${lg(2,'12')} + ${lg(2,'(4/3)')} ?`,lab:'valeur =',ans:4,
   why:'La somme vaut log₂(12 · 4/3) = log₂ 16 = 4, car 2⁴ = 16.'},
  {h:'Changer de base',p:`<p>Une calculatrice ne connaît qu’une ou deux bases. Comment obtenir log<sub>7</sub> 50 ? Tous les logarithmes sont <b>proportionnels</b> entre eux.</p>`
   +PROP(`Pour <i>a</i>, <i>b</i> &gt; 0 différents de 1 et <i>x</i> &gt; 0 : <b>log<sub><i>b</i></sub> <i>x</i> = ${F(lg('<i>a</i>','<i>x</i>'),lg('<i>a</i>','<i>b</i>'))}</b>. En particulier log<sub><i>b</i></sub> <i>a</i> = 1/log<sub><i>a</i></sub> <i>b</i>.`)
   +WHY(`Par définition, <i>x</i> = <i>b</i><sup>log<sub><i>b</i></sub> <i>x</i></sup>. Prenons le logarithme de base <i>a</i> des deux côtés et sortons l’exposant : log<sub><i>a</i></sub> <i>x</i> = log<sub><i>b</i></sub> <i>x</i> · log<sub><i>a</i></sub> <i>b</i>. Il reste à diviser par log<sub><i>a</i></sub> <i>b</i>, non nul car <i>b</i> ≠ 1. Avec <i>x</i> = <i>a</i>, on obtient log<sub><i>b</i></sub> <i>a</i> · log<sub><i>a</i></sub> <i>b</i> = 1.`)
   +EX(`log<sub>8</sub> 32 = ${F(lg(2,'32'),lg(2,'8'))} = 5/3. Vérification : 8<sup>5/3</sup> = (8<sup>1/3</sup>)⁵ = 2⁵ = 32. &nbsp; log<sub>7</sub> 50 = log<sub>10</sub> 50 / log<sub>10</sub> 7 ≈ 1,699/0,845 ≈ 2,01.`)
   +IDEA(`La formule dit que la courbe de log<sub><i>b</i></sub> est celle de log<sub><i>a</i></sub> étirée verticalement d’un facteur constant. Une seule fonction logarithme suffit donc à toutes les engendrer.`)
   +WARN(`log<sub><i>a</i></sub> <i>x</i> / log<sub><i>a</i></sub> <i>b</i> n’est pas log<sub><i>a</i></sub>(<i>x</i>/<i>b</i>). Le premier est un quotient de deux nombres, le second le logarithme d’un quotient.`)},
  {h:'Une base peu commode',p:`Que vaut ${lg(27,'9')} ? Donne une fraction.`,lab:'log₂₇ 9 =',ans:2/3,tol:1e-6,
   why:'En base 3 : log₃ 9 / log₃ 27 = 2/3. Vérification : 27^(2/3) = (27^(1/3))² = 3² = 9.'},
  {kind:'Méthode',h:'Résoudre une équation exponentielle',
   p:'<b>Quand :</b> l’inconnue est en exposant. <b>Pourquoi ça marche :</b> exp<sub><i>a</i></sub> prend chaque valeur une seule fois, donc <b><i>a</i><sup><i>u</i></sup> = <i>a</i><sup><i>v</i></sup> ⇔ <i>u</i> = <i>v</i></b> ; et <i>a</i><sup><i>u</i></sup> = <i>k</i> (avec <i>k</i> &gt; 0) ⇔ <i>u</i> = log<sub><i>a</i></sub> <i>k</i>. <b>Comment :</b><ol><li>ramène tout à <b>une seule base</b> (4 = 2², 1/8 = 2<sup>−3</sup>, 9<sup><i>x</i></sup> = (3<sup><i>x</i></sup>)²) ;</li><li>si on obtient <i>a</i><sup><i>u</i></sup> = <i>a</i><sup><i>v</i></sup>, égale les exposants ;</li><li>si <i>a</i><sup><i>x</i></sup> apparaît à plusieurs puissances, pose <i>y</i> = <i>a</i><sup><i>x</i></sup> : on obtient une équation ordinaire en <i>y</i>, dont on ne garde que les solutions <b>strictement positives</b> ;</li><li>reviens à <i>x</i> avec le logarithme.</li></ol>',
   demo:{enonce:`Résoudre 9<sup>${x}</sup> − 4 · 3<sup>${x}</sup> + 3 = 0.`,
    etapes:[{f:`9<sup>${x}</sup> = (3²)<sup>${x}</sup> = (3<sup>${x}</sup>)²`,w:'Une seule base : 3. Le terme 9ˣ est le carré de 3ˣ.'},
     {f:`On pose <i>y</i> = 3<sup>${x}</sup> &gt; 0 : <i>y</i>² − 4<i>y</i> + 3 = 0`,w:'L’équation devient du second degré en y.'},
     {f:'(<i>y</i> − 1)(<i>y</i> − 3) = 0, donc <i>y</i> = 1 ou <i>y</i> = 3',w:'Les deux racines sont positives : on les garde toutes les deux.'},
     {f:`3<sup>${x}</sup> = 1 ⇔ ${x} = 0 ; &nbsp; 3<sup>${x}</sup> = 3 ⇔ ${x} = 1`,w:'On revient à x : log₃ 1 = 0 et log₃ 3 = 1.'}],
    conclusion:'Les solutions sont <i>x</i> = 0 et <i>x</i> = 1. Vérification : 1 − 4 + 3 = 0 et 9 − 12 + 3 = 0.'},
   note:'Si une racine y est négative ou nulle, elle ne donne aucun x : aˣ > 0 toujours. Et 2ˣ = 5 a une solution, x = log₂ 5 ≈ 2,32, qu’on laisse sous cette forme.'},
  {h:'Une seule base',p:`Résous 2<sup>${x}+1</sup> · 4<sup>${x}</sup> = 128.`,lab:'x =',ans:2,
   why:'4ˣ = 2²ˣ, donc le membre de gauche vaut 2^(x+1+2x) = 2^(3x+1). Et 128 = 2⁷. Donc 3x + 1 = 7, soit x = 2.'},
  {kind:'Méthode',h:'Résoudre une inéquation exponentielle',
   p:'<b>Quand :</b> l’inconnue est en exposant et le signe est &lt;, ≤, &gt; ou ≥. <b>Pourquoi ça marche :</b> une fonction strictement monotone conserve ou renverse les inégalités. Si <i>a</i> &gt; 1, exp<sub><i>a</i></sub> est croissante : <b><i>a</i><sup><i>u</i></sup> &lt; <i>a</i><sup><i>v</i></sup> ⇔ <i>u</i> &lt; <i>v</i></b>. Si 0 &lt; <i>a</i> &lt; 1, elle est décroissante : <b><i>a</i><sup><i>u</i></sup> &lt; <i>a</i><sup><i>v</i></sup> ⇔ <i>u</i> &gt; <i>v</i></b>, le sens <b>se renverse</b>. De même, pour <i>k</i> &gt; 0, <i>a</i><sup><i>u</i></sup> &lt; <i>k</i> ⇔ <i>u</i> &lt; log<sub><i>a</i></sub> <i>k</i> si <i>a</i> &gt; 1 (et <i>u</i> &gt; log<sub><i>a</i></sub> <i>k</i> si <i>a</i> &lt; 1). <b>Comment :</b> une seule base, puis compare les exposants en regardant si la base est plus grande ou plus petite que 1.',
   demo:{enonce:`Résoudre (1/2)<sup>${x}</sup> &lt; 1/8.`,
    etapes:[{f:`1/8 = (1/2)³, donc (1/2)<sup>${x}</sup> &lt; (1/2)³`,w:'Une seule base, 1/2.'},
     {f:'La base 1/2 est plus petite que 1 : exp<sub>1/2</sub> est décroissante.',w:'C’est le moment de décider si l’inégalité se conserve ou se renverse.'},
     {f:`(1/2)<sup>${x}</sup> &lt; (1/2)³ ⇔ ${x} &gt; 3`,w:'Base inférieure à 1 : on renverse le sens.'}],
    conclusion:'L’ensemble des solutions est ]3 ; +∞[. Contrôle : x = 4 donne 1/16 < 1/8, juste ; x = 2 donne 1/4, qui n’est pas inférieur à 1/8.'},
   note:'Avec 2ˣ < 1/8, on écrirait 2ˣ < 2⁻³ ⇔ x < −3 : même valeur frontière, mais côté opposé. Contrôle toujours avec une valeur.'},
  {h:'Attention à la base',p:`Quel est l’ensemble des solutions de 0,2<sup>${x}−1</sup> ≥ 25 ?`,
   opts:['<i>x</i> ≥ −1','<i>x</i> ≤ 3','<i>x</i> ≤ −1','<i>x</i> ≥ 3'],ans:2,
   why:'0,2 = 1/5 et 25 = 5² = (1/5)⁻². L’inéquation devient (1/5)^(x−1) ≥ (1/5)⁻². La base 1/5 est inférieure à 1, donc x − 1 ≤ −2, soit x ≤ −1. Contrôle : x = −1 donne 0,2⁻² = 25.'},
  {kind:'Récapitulatif',h:'Ce qu’il faut retenir',p:`<p>Les objets du chapitre et les gestes qui vont avec.</p>`
   +KEEP(`<ul><li><b><i>a</i><sup><i>x</i></sup></b> pour <i>x</i> réel : borne supérieure des <i>a</i><sup><i>r</i></sup>, <i>r</i> rationnel ≤ <i>x</i> (pour <i>a</i> &gt; 1). C’est l’unique prolongement croissant et continu.</li><li><b>Règles :</b> <i>a</i><sup><i>x</i>+<i>y</i></sup> = <i>a</i><sup><i>x</i></sup><i>a</i><sup><i>y</i></sup>, (<i>a</i><sup><i>x</i></sup>)<sup><i>y</i></sup> = <i>a</i><sup><i>xy</i></sup>, (<i>ab</i>)<sup><i>x</i></sup> = <i>a</i><sup><i>x</i></sup><i>b</i><sup><i>x</i></sup>, <i>a</i><sup><i>x</i></sup> &gt; 0.</li><li><b>exp<sub><i>a</i></sub></b> : continue, passe par (0 ; 1), croissante si <i>a</i> &gt; 1, décroissante si <i>a</i> &lt; 1, bijection de ℝ sur ]0 ; +∞[.</li><li><b>log<sub><i>a</i></sub> <i>y</i></b> = l’exposant <i>x</i> tel que <i>a</i><sup><i>x</i></sup> = <i>y</i> (<i>y</i> &gt; 0). Réciproque de exp<sub><i>a</i></sub>, même sens de variation.</li><li><b>Propriétés :</b> log(<i>xy</i>) = log <i>x</i> + log <i>y</i>, log(<i>x</i>/<i>y</i>) = log <i>x</i> − log <i>y</i>, log(<i>x</i><sup><i>r</i></sup>) = <i>r</i> log <i>x</i>, log<sub><i>a</i></sub> 1 = 0, log<sub><i>a</i></sub> <i>a</i> = 1.</li><li><b>Changement de base :</b> log<sub><i>b</i></sub> <i>x</i> = log<sub><i>a</i></sub> <i>x</i> / log<sub><i>a</i></sub> <i>b</i>.</li><li><b>Équations :</b> une seule base, puis <i>a</i><sup><i>u</i></sup> = <i>a</i><sup><i>v</i></sup> ⇔ <i>u</i> = <i>v</i> ; poser <i>y</i> = <i>a</i><sup><i>x</i></sup> si besoin, garder <i>y</i> &gt; 0.</li><li><b>Inéquations :</b> même sens si <i>a</i> &gt; 1, sens renversé si <i>a</i> &lt; 1.</li></ul>`)},
  {kind:'Problème',h:'Une culture de bactéries',
   p:'Dans une boîte, une population de bactéries double toutes les 3 heures. À l’instant <i>t</i> = 0 (en heures), on compte 500 bactéries. Le nombre de bactéries au temps <i>t</i> est donc <i>N</i>(<i>t</i>) = 500 · 2<sup><i>t</i>/3</sup>. On veut lire cette formule dans les deux sens : du temps vers la population, puis de la population vers le temps.',
   fig:(()=>{ const P=plane({x:[-1,20],y:[-2000,34000],w:320,h:220,step:4,grid:false,lx:3}); P.fn(t=>500*2**(t/3),{from:0,to:19.5}); for(let k=0;k<=6;k++) P.dot(3*k,500*2**k,{r:4,c:'var(--spark)'}); P.text(1,30000,'N(t) = 500 · 2^(t/3)',{c:'var(--accent)'}); return P.svg(); })(),
   parts:[
    {q:'a) Combien de bactéries y a-t-il après 9 heures ?',lab:'N(9) =',ans:4000,hint:'9/3 = 3 doublements.',why:'N(9) = 500 · 2³ = 500 · 8 = 4000.'},
    {q:'b) Au bout de combien d’heures la population atteint-elle 32 000 bactéries ?',lab:'t =',unit:'h',ans:18,hint:'Résous 2^(t/3) = 64 en écrivant 64 comme une puissance de 2.',why:'500 · 2^(t/3) = 32 000 ⇔ 2^(t/3) = 64 = 2⁶ ⇔ t/3 = 6 ⇔ t = 18 h.'},
    {q:'c) Quelle formule donne le temps <i>t</i> nécessaire pour atteindre une population <i>N</i> quelconque ?',opts:['<i>t</i> = 3 log<sub>2</sub>(<i>N</i>/500)','<i>t</i> = log<sub>2</sub>(3<i>N</i>/500)','<i>t</i> = 3 log<sub>2</sub> <i>N</i> − 500','<i>t</i> = (1/3) log<sub>2</sub>(<i>N</i>/500)'],ans:0,hint:'Isole 2^(t/3), puis prends le logarithme de base 2 des deux côtés.',why:'2^(t/3) = N/500 ⇔ t/3 = log₂(N/500) ⇔ t = 3 log₂(N/500). Contrôle avec b) : 3 log₂ 64 = 18.'},
    {q:'d) Au bout de combien d’heures y a-t-il 2000√2 bactéries ?',lab:'t =',unit:'h',ans:7.5,tol:1e-6,hint:'Écris 2000√2 / 500 = 4√2 comme une puissance de 2 à exposant fractionnaire.',why:'N/500 = 4√2 = 2² · 2^(1/2) = 2^(5/2). Donc t/3 = 5/2 et t = 7,5 h.'},
   ],
   sol:'N(9) = 500 · 2³ = 4000. Pour N = 32 000, on isole la puissance : 2^(t/3) = 64 = 2⁶, et comme exp₂ prend chaque valeur une seule fois, t/3 = 6, donc t = 18 h. En général, 2^(t/3) = N/500 équivaut à t/3 = log₂(N/500), d’où <b>t = 3 log₂(N/500)</b> : c’est la fonction réciproque, du nombre de bactéries vers le temps. Pour N = 2000√2, N/500 = 4√2 = 2^(5/2) : t = 3 · 5/2 = 7,5 h. Le logarithme n’est rien d’autre que la lecture de la formule à l’envers.'},
  {kind:'Problème',h:'log₂ 3 n’est pas un rationnel',
   p:'On veut démontrer que le nombre log<sub>2</sub> 3 est irrationnel, par l’absurde. On suppose qu’il s’écrit <i>p</i>/<i>q</i> avec <i>p</i> et <i>q</i> entiers strictement positifs, et on cherche une contradiction à partir d’une égalité entre entiers. On termine par un calcul qui utilise le changement de base.',
   parts:[
    {q:'a) Entre quels entiers consécutifs se trouve log<sub>2</sub> 3 ? Donne le plus petit entier strictement supérieur à log<sub>2</sub> 3.',lab:'entier =',ans:2,hint:'Compare 3 avec les puissances 2¹ et 2².',why:'2¹ = 2 < 3 < 4 = 2², et log₂ est croissante, donc 1 < log₂ 3 < 2. En particulier log₂ 3 n’est pas entier, et p/q > 0.'},
    {q:'b) Si log<sub>2</sub> 3 = <i>p</i>/<i>q</i>, quelle égalité entre entiers en découle ?',opts:['2<i>p</i> = 3<i>q</i>','2<sup><i>p</i></sup> = 3<sup><i>q</i></sup>','2<sup><i>q</i></sup> = 3<sup><i>p</i></sup>','<i>p</i>² = 3<i>q</i>²'],ans:1,hint:'Par définition, 2^(log₂ 3) = 3. Élève ensuite à la puissance q.',why:'log₂ 3 = p/q signifie 2^(p/q) = 3. En élevant à la puissance q : (2^(p/q))^q = 2^p = 3^q.'},
    {q:'c) Pourquoi cette égalité est-elle impossible ?',opts:['Parce que 2<sup><i>p</i></sup> est pair (<i>p</i> ≥ 1) et 3<sup><i>q</i></sup> est impair','Parce que 2<sup><i>p</i></sup> &lt; 3<sup><i>q</i></sup> pour tous <i>p</i>, <i>q</i>','Parce que <i>p</i> et <i>q</i> ne peuvent pas être tous les deux positifs','Parce qu’une puissance de 2 n’est jamais un entier'],ans:0,hint:'Regarde la parité des deux membres.',why:'p ≥ 1, donc 2^p = 2 · 2^(p−1) est pair. Un produit d’entiers impairs est impair, donc 3^q est impair. Un entier ne peut pas être à la fois pair et impair : contradiction, log₂ 3 est irrationnel.'},
    {q:'d) Calcule log<sub>2</sub> 3 · log<sub>3</sub> 16.',lab:'valeur =',ans:4,hint:'Change la base de log₃ 16 pour passer en base 2.',why:'log₃ 16 = log₂ 16 / log₂ 3 = 4/log₂ 3. Le produit vaut donc 4. Les deux facteurs sont irrationnels, leur produit est entier.'},
   ],
   sol:'Comme 2 < 3 < 4, on a 1 < log₂ 3 < 2 : ce n’est pas un entier. Supposons log₂ 3 = p/q avec p, q ∈ ℕ*. Alors 2^(p/q) = 3, et en élevant à la puissance q, 2^p = 3^q. Le membre de gauche est pair (p ≥ 1), le membre de droite est impair (produit de nombres impairs) : impossible. Donc <b>log₂ 3 est irrationnel</b>. Enfin, par changement de base, log₃ 16 = log₂ 16 / log₂ 3, donc log₂ 3 · log₃ 16 = log₂ 16 = 4. Le même raisonnement montre que log₂ n est irrationnel dès que n n’est pas une puissance de 2.'},
]},
/* ===================== 2. LIMITE D’UNE FONCTION EN UN POINT ===================== */
{subj:'gred',sem:'ana',id:'gred-limite-fonction',h:'Limite d’une fonction en un point',p:'Que fait f(x) quand x s’approche de a ? La définition ε–δ, son lien avec la continuité, les limites à gauche et à droite, infinies, en ±∞, et les premières formes indéterminées.',steps:[
  {h:'Que fait f près de a quand f(a) n’existe pas ?',p:`<p>Prenons f(<i>x</i>) = ${F(x+'² − 1',x+' − 1')}. En <i>x</i> = 1, le calcul donne 0/0 : f(1) <b>n’existe pas</b>. Pourtant, rien n’empêche de calculer f(0,9), f(0,99), f(1,01)… Déplace le curseur : les valeurs se rapprochent de 2, par la gauche comme par la droite.</p>`
   +IDEA(`Pour <i>x</i> ≠ 1, on peut simplifier : f(<i>x</i>) = ${F('('+x+' − 1)('+x+' + 1)',x+' − 1')} = <i>x</i> + 1. Le graphe est la droite <i>y</i> = <i>x</i> + 1 <b>privée du point (1 ; 2)</b>. Quand <i>x</i> s’approche de 1, f(<i>x</i>) s’approche de 2, sans jamais avoir besoin de la valeur en 1. On dira que <b>la limite de f en 1 vaut 2</b>, et on écrira ${L(1)} f(<i>x</i>) = 2.`)
   +`<p>Un tableau de valeurs suggère ce nombre, mais ne le définit pas : il faudrait pouvoir dire « f(<i>x</i>) est <b>aussi proche qu’on veut</b> de 2 dès que <i>x</i> est <b>assez proche</b> de 1 ». C’est exactement ce que la définition de l’étape suivante rend précis. La notion de limite est l’outil de toute l’analyse : la continuité, la dérivée et l’intégrale en dépendent.</p>`,
   params:[{id:'d',l:'Distance de x à 1',min:.05,max:1,step:.05,v:1}],
   draw:v=>{ const P=plane({x:[-1,3],y:[-.5,4],h:300,lab:1}); P.fn(t=>t+1); hole(P,1,2,.09); P.dot(1-v.d,2-v.d,{r:5,c:'var(--math)',l:'x &lt; 1',dx:-45}).dot(1+v.d,2+v.d,{r:5,c:'var(--spark)',l:'x &gt; 1'}); return P.svg(); },
   info:v=>`f(${fmt(1-v.d)}) = ${fmt(2-v.d)} et f(${fmt(1+v.d)}) = ${fmt(2+v.d)} : les deux valeurs sont à ${fmt(v.d)} de 2.`},
  {h:'La définition ε–δ de la limite',p:`<p>Soit f définie sur un ensemble <i>D</i>, et <i>a</i> un réel dont tout voisinage contient des points de <i>D</i> autres que <i>a</i> (f peut être définie en <i>a</i> ou non).</p>`
   +DEF(`On dit que f a pour <b>limite</b> <i>L</i> en <i>a</i>, et on écrit <b>${L('<i>a</i>')} f(<i>x</i>) = <i>L</i></b>, si : <b>∀ε &gt; 0, ∃δ &gt; 0, ∀<i>x</i> ∈ <i>D</i>, 0 &lt; |<i>x</i> − <i>a</i>| &lt; δ ⇒ |f(<i>x</i>) − <i>L</i>| &lt; ε</b>.`)
   +IDEA(`Lis-la comme un défi en deux temps. Un adversaire choisit une <b>tolérance</b> ε, aussi petite qu’il veut : il exige que f(<i>x</i>) soit dans la bande horizontale ]<i>L</i> − ε ; <i>L</i> + ε[. Tu réponds par un <b>rayon</b> δ : tu promets que tous les <i>x</i> de la bande verticale ]<i>a</i> − δ ; <i>a</i> + δ[ (sauf <i>a</i> lui-même) envoient leur image dans la bande horizontale. La limite vaut <i>L</i> si tu peux gagner <b>pour tout ε</b>. La condition 0 &lt; |<i>x</i> − <i>a</i>| exclut <i>x</i> = <i>a</i> : la valeur f(<i>a</i>) ne compte pas, et peut ne pas exister.`)
   +EX(`Ici f(<i>x</i>) = <i>x</i>², <i>a</i> = 1, <i>L</i> = 1. Règle ε, puis cherche un δ qui marche : la portion de courbe dans la bande verticale doit rester dans la bande horizontale. Pour |<i>x</i> − 1| &lt; δ ≤ 1, on a |<i>x</i>² − 1| = |<i>x</i> − 1| · |<i>x</i> + 1| &lt; δ(2 + δ). Il suffit donc que δ(2 + δ) ≤ ε. Un δ plus petit qu’un δ qui marche marche aussi.`),
   params:[{id:'e',l:'Tolérance ε',min:.1,max:1,step:.1,v:.5},{id:'d',l:'Rayon δ',min:.05,max:1,step:.05,v:.6}],
   draw:v=>{ const okk=v.d*(2+v.d)<=v.e+1e-9, P=plane({x:[-.6,2.4],y:[-.5,4.2],h:300,lab:1});
     P.rect(-.6,1-v.e,3,2*v.e,{fill:'var(--spark)',fo:.18,c:null}).rect(1-v.d,-.5,2*v.d,4.7,{fill:'var(--math)',fo:.15,c:null});
     P.seg(-.6,1-v.e,2.4,1-v.e,{c:'var(--spark)',w:1.5,dash:true}).seg(-.6,1+v.e,2.4,1+v.e,{c:'var(--spark)',w:1.5,dash:true});
     P.fn(t=>t*t,{c:'var(--muted)',w:2}).fn(t=>t*t,{from:1-v.d,to:1+v.d,c:okk?'var(--ok)':'var(--bad)',w:4}).dot(1,1,{r:5,c:'var(--ink)',l:'(a ; L)'});
     P.text(2.35,1+v.e,'L + ε',{a:'end',dy:-5,c:'var(--spark)',s:11}).text(2.35,1-v.e,'L − ε',{a:'end',dy:14,c:'var(--spark)',s:11}); return P.svg(); },
   info:v=>{ const m=v.d*(2+v.d); return `Sur la bande |<i>x</i> − 1| &lt; ${fmt(v.d)}, l’écart |<i>x</i>² − 1| reste sous δ(2 + δ) = ${fmt(m,4)}. ${m<=v.e+1e-9?`C’est ≤ ε = ${fmt(v.e)} : <b>ce δ convient</b>.`:`C’est &gt; ε = ${fmt(v.e)} : <b>ce δ est trop grand</b>, une partie de la courbe sort de la bande.`}`; }},
  {kind:'Pratique',h:'Réponds au défi',p:`Toujours avec f(<i>x</i>) = <i>x</i>² en <i>a</i> = 1, l’adversaire a choisi <b>ε = 0,3</b>. Règle un rayon δ qui convient : toute la portion de courbe dans la bande verticale doit rester dans la bande horizontale ]0,7 ; 1,3[.`,
   params:[{id:'d',l:'Rayon δ',min:.05,max:.5,step:.05,v:.4}],
   draw:v=>{ const e=.3, okk=v.d*(2+v.d)<=e+1e-9, P=plane({x:[0,2],y:[-.2,3],h:300,step:.5,lab:.5});
     P.rect(0,1-e,2,2*e,{fill:'var(--spark)',fo:.18,c:null}).rect(1-v.d,-.2,2*v.d,3.2,{fill:'var(--math)',fo:.15,c:null});
     P.fn(t=>t*t,{c:'var(--muted)',w:2}).fn(t=>t*t,{from:1-v.d,to:1+v.d,c:okk?'var(--ok)':'var(--bad)',w:4}).dot(1,1,{r:5,c:'var(--ink)'}); return P.svg(); },
   info:v=>`Écart maximal sur la bande : (1 + δ)² − 1 = ${fmt((1+v.d)**2-1,4)} (à comparer à ε = 0,3).`,
   ok:v=>v.d*(2+v.d)<=.3+1e-9,
   why:'Il faut (1 + δ)² − 1 = 2δ + δ² ≤ 0,3. Avec δ = 0,1 : 0,21 ≤ 0,3, ça marche (et δ = 0,05 aussi). Avec δ = 0,15 : 0,3225 > 0,3, le point x = 1,15 sort de la bande.'},
  {kind:'Méthode',h:'Prouver une limite avec ε–δ',
   p:`<b>Quand :</b> on demande de démontrer ${L('<i>a</i>')} f(<i>x</i>) = <i>L</i> « avec la définition ». <b>Pourquoi ça marche :</b> on doit, pour un ε quelconque, exhiber un δ. Le travail consiste à <b>majorer</b> |f(<i>x</i>) − <i>L</i>| par une expression simple en |<i>x</i> − <i>a</i>|, puis à lire quelle contrainte sur |<i>x</i> − <i>a</i>| garantit que cette expression est plus petite que ε. <b>Comment :</b><ol><li>écris |f(<i>x</i>) − <i>L</i>| et fais apparaître le facteur |<i>x</i> − <i>a</i>| ;</li><li>majore l’autre facteur par une constante <i>C</i> (au besoin en se limitant à |<i>x</i> − <i>a</i>| &lt; 1) ;</li><li>choisis δ = ε/<i>C</i> (ou min(1, ε/<i>C</i>)) et rédige : « soit ε &gt; 0 ; posons δ = … ; si 0 &lt; |<i>x</i> − <i>a</i>| &lt; δ alors … &lt; ε ».</li></ol>`,
   demo:{enonce:`Démontrer que ${L(2)} (3<i>x</i> − 1) = 5.`,
    etapes:[{f:'|f(<i>x</i>) − 5| = |3<i>x</i> − 1 − 5| = |3<i>x</i> − 6| = 3|<i>x</i> − 2|',w:'On fait apparaître |x − a| = |x − 2| en factorisant.'},
     {f:'On veut 3|<i>x</i> − 2| &lt; ε, c’est-à-dire |<i>x</i> − 2| &lt; ε/3',w:'On lit la contrainte sur |x − 2| qui suffit.'},
     {f:'Soit ε &gt; 0. Posons δ = ε/3. Si 0 &lt; |<i>x</i> − 2| &lt; δ, alors |f(<i>x</i>) − 5| = 3|<i>x</i> − 2| &lt; 3δ = ε.',w:'La rédaction finale suit l’ordre de la définition : ε d’abord, δ ensuite, puis la vérification.'}],
    conclusion:`On a trouvé un δ pour tout ε : ${L(2)} (3<i>x</i> − 1) = 5. Pour une fonction affine <i>mx</i> + <i>p</i> (<i>m</i> ≠ 0), δ = ε/|<i>m</i>| convient toujours.`},
   note:'Le δ n’est pas unique : tout δ plus petit convient aussi. On cherche un δ qui marche, pas le meilleur.'},
  {h:'Trouve le rayon',p:`On veut prouver ${L(1)} (5<i>x</i> + 2) = 7 avec la définition. L’adversaire choisit ε = 0,1. Quel est le plus grand δ qui convient ?`,lab:'δ =',ans:.02,tol:1e-9,
   why:'|5x + 2 − 7| = 5|x − 1| < 0,1 ⇔ |x − 1| < 0,02. Le plus grand rayon est δ = 0,1/5 = 0,02.'},
  {h:'Limite, continuité et unicité',p:`<p>La définition de la limite ressemble beaucoup à celle de la continuité. Comparons-les.</p>`
   +RAP(`f est <b>continue en <i>a</i></b> ∈ <i>D</i> si ∀ε &gt; 0, ∃δ &gt; 0, ∀<i>x</i> ∈ <i>D</i>, |<i>x</i> − <i>a</i>| &lt; δ ⇒ |f(<i>x</i>) − f(<i>a</i>)| &lt; ε.`)
   +PROP(`Si <i>a</i> ∈ <i>D</i> : <b>f est continue en <i>a</i> ⇔ ${L('<i>a</i>')} f(<i>x</i>) = f(<i>a</i>)</b>. Si <i>a</i> ∉ <i>D</i> et si ${L('<i>a</i>')} f(<i>x</i>) = <i>L</i> existe, la fonction prolongée par f(<i>a</i>) = <i>L</i> est continue en <i>a</i> : c’est le <b>prolongement par continuité</b>.`)
   +WHY(`Les deux phrases ne diffèrent que par la condition 0 &lt; |<i>x</i> − <i>a</i>| et par <i>L</i> = f(<i>a</i>). Si la limite vaut f(<i>a</i>), le cas <i>x</i> = <i>a</i> donne |f(<i>a</i>) − f(<i>a</i>)| = 0 &lt; ε : la continuité suit. Réciproquement, la continuité donne la limite en oubliant simplement le point <i>x</i> = <i>a</i>.`)
   +THM(`<b>Unicité.</b> Si f admet une limite en <i>a</i>, elle n’en admet qu’une.`)
   +WHY(`Supposons deux limites <i>L</i> ≠ <i>L</i>′ et prenons ε = |<i>L</i> − <i>L</i>′|/2. Pour <i>x</i> assez proche de <i>a</i>, f(<i>x</i>) serait à moins de ε de <i>L</i> et à moins de ε de <i>L</i>′, donc |<i>L</i> − <i>L</i>′| ≤ |<i>L</i> − f(<i>x</i>)| + |f(<i>x</i>) − <i>L</i>′| &lt; 2ε = |<i>L</i> − <i>L</i>′| : absurde. Les deux bandes horizontales ne se touchent pas, f(<i>x</i>) ne peut pas être dans les deux.`)
   +EX(`Les polynômes, les racines, les exponentielles sont continus là où ils sont définis : ${L(3)} (<i>x</i>² + 1) = 3² + 1 = 10, directement. Et f(<i>x</i>) = (<i>x</i>² − 1)/(<i>x</i> − 1), non définie en 1, se prolonge par f(1) = 2.`)},
  {h:'Opérations sur les limites et formes indéterminées',p:`<p>On ne revient pas à ε–δ à chaque calcul : les limites se combinent comme les limites de suites.</p>`
   +PROP(`Si ${L('<i>a</i>')} f(<i>x</i>) = <i>L</i> et ${L('<i>a</i>')} g(<i>x</i>) = <i>L</i>′ (réels), alors en <i>a</i> : f + g → <i>L</i> + <i>L</i>′, f · g → <i>L</i> · <i>L</i>′, <i>k</i>f → <i>kL</i>, et f/g → <i>L</i>/<i>L</i>′ si <i>L</i>′ ≠ 0. Si de plus <i>u</i> → <i>b</i> en <i>a</i> et g est continue en <i>b</i>, alors g(<i>u</i>(<i>x</i>)) → g(<i>b</i>).`)
   +WHY(`Pour la somme : |f + g − (<i>L</i> + <i>L</i>′)| ≤ |f − <i>L</i>| + |g − <i>L</i>′|. Pour ε donné, on prend δ₁ qui rend le premier écart &lt; ε/2 et δ₂ pour le second ; δ = min(δ₁, δ₂) rend la somme &lt; ε. Les autres règles se prouvent par des majorations du même genre.`)
   +EX(`${L(2)} ${F(x+'² + 3',x+' − 1')} = ${F('4 + 3','2 − 1')} = 7 : le numérateur tend vers 7, le dénominateur vers 1 ≠ 0.`)
   +WARN(`La règle du quotient exige <i>L</i>′ ≠ 0. Si <i>L</i> = <i>L</i>′ = 0, on a une <b>forme indéterminée 0/0</b> : la limite peut valoir n’importe quoi (ou ne pas exister), selon les fonctions. Les quatre formes indéterminées sont <b>0/0</b>, <b>∞/∞</b>, <b>0 · ∞</b> et <b>∞ − ∞</b>. « Indéterminée » veut dire « les règles ne concluent pas » : il faut transformer l’expression avant de passer à la limite. Les méthodes de fin de chapitre servent à ça.`)},
  {h:'Limite à gauche, limite à droite',p:`<p>Parfois f se comporte différemment selon le côté par lequel <i>x</i> s’approche de <i>a</i>. Ici f(<i>x</i>) = <i>x</i> + <i>x</i>/|<i>x</i>|, c’est-à-dire <i>x</i> − 1 pour <i>x</i> &lt; 0 et <i>x</i> + 1 pour <i>x</i> &gt; 0.</p>`
   +DEF(`<b>Limite à droite</b> : ${L('<i>a</i>⁺')} f(<i>x</i>) = <i>L</i> si ∀ε &gt; 0, ∃δ &gt; 0, <b>0 &lt; <i>x</i> − <i>a</i> &lt; δ</b> ⇒ |f(<i>x</i>) − <i>L</i>| &lt; ε. <b>Limite à gauche</b> : ${L('<i>a</i>⁻')} f(<i>x</i>) = <i>L</i>, avec <b>0 &lt; <i>a</i> − <i>x</i> &lt; δ</b>.`)
   +THM(`f admet une limite en <i>a</i> si et seulement si f admet une limite à gauche et une limite à droite en <i>a</i>, <b>et qu’elles sont égales</b>. Leur valeur commune est alors la limite.`)
   +WHY(`Si la limite existe, le même δ convient des deux côtés. Réciproquement, si les deux limites latérales valent <i>L</i>, on a un δ₁ à gauche et un δ₂ à droite pour le même ε ; δ = min(δ₁, δ₂) marche des deux côtés, donc pour tout <i>x</i> avec 0 &lt; |<i>x</i> − <i>a</i>| &lt; δ.`)
   +EX(`Pour la fonction de la figure, ${L('0⁻')} f(<i>x</i>) = −1 et ${L('0⁺')} f(<i>x</i>) = 1. Les deux limites existent mais diffèrent : <b>f n’a pas de limite en 0</b>. Déplace le curseur : les deux points ne se rejoignent jamais.`)
   +WARN(`Les limites latérales servent surtout aux fonctions définies par morceaux, aux valeurs absolues et aux dénominateurs qui changent de signe. Quand on parle de « la limite », on exige les deux côtés.`),
   params:[{id:'h',l:'Distance h à 0',min:.05,max:1.5,step:.05,v:1.2}],
   draw:v=>{ const P=plane({x:[-3,3],y:[-4,4],h:300,lab:1}); P.fn(t=>t-1,{from:-3,to:-.005}).fn(t=>t+1,{from:.005,to:3}); hole(P,0,-1,.12); hole(P,0,1,.12);
     P.dot(-v.h,-v.h-1,{r:5,c:'var(--math)',l:'gauche',dx:-52}).dot(v.h,v.h+1,{r:5,c:'var(--spark)',l:'droite'}); return P.svg(); },
   info:v=>`f(−${fmt(v.h)}) = ${fmt(-v.h-1)} → −1 &nbsp;·&nbsp; f(${fmt(v.h)}) = ${fmt(v.h+1)} → 1. Écart entre les deux images : ${fmt(2*v.h+2)}, jamais nul.`},
  {h:'Un seul côté',p:`Calcule ${L('2⁻')} ${F(x+'² − 4','|'+x+' − 2|')}.`,lab:'limite =',ans:-4,
   why:'Pour x < 2, |x − 2| = −(x − 2) = 2 − x. Le quotient vaut (x − 2)(x + 2)/(2 − x) = −(x + 2), qui tend vers −4. (À droite, on obtiendrait +4 : pas de limite en 2.)'},
  {h:'Limite infinie en un point',p:`<p>Près de 0, 1/<i>x</i>² ne s’approche d’aucun nombre : les valeurs dépassent tout ce qu’on veut. On dit que la limite est +∞.</p>`
   +DEF(`${L('<i>a</i>')} f(<i>x</i>) = <b>+∞</b> si <b>∀<i>A</i> &gt; 0, ∃δ &gt; 0, 0 &lt; |<i>x</i> − <i>a</i>| &lt; δ ⇒ f(<i>x</i>) &gt; <i>A</i></b>. De même ${L('<i>a</i>')} f(<i>x</i>) = −∞ avec f(<i>x</i>) &lt; −<i>A</i>. On définit pareillement les limites infinies à gauche et à droite.`)
   +IDEA(`Toutes ces définitions ont la même forme : « pour tout <b>voisinage</b> <i>V</i> de la cible, il existe un voisinage <i>U</i> de <i>a</i> tel que f envoie <i>U</i> ∖ {<i>a</i>} dans <i>V</i> ». Un voisinage d’un réel <i>L</i> est un intervalle ]<i>L</i> − ε ; <i>L</i> + ε[ ; un voisinage de +∞ est un intervalle ]<i>A</i> ; +∞[. La bande horizontale est simplement remplacée par un demi-plan.`)
   +EX(`${L(0)} 1/<i>x</i>² = +∞ : pour <i>A</i> &gt; 0, posons δ = 1/√<i>A</i> ; si 0 &lt; |<i>x</i>| &lt; δ alors <i>x</i>² &lt; 1/<i>A</i>, donc 1/<i>x</i>² &gt; <i>A</i>. En revanche 1/<i>x</i> → +∞ à droite de 0 et −∞ à gauche : <b>pas de limite en 0</b>, même infinie.`)
   +PROP(`<b>Règle « nombre sur 0 »</b> : si f → <i>k</i> ≠ 0 et g → 0 en gardant un signe constant près de <i>a</i>, alors f/g → ±∞ selon la règle des signes. On note g → 0⁺ ou 0⁻. Ce n’est <b>pas</b> une forme indéterminée.`)
   +WARN(`+∞ n’est pas un nombre : écrire « f(<i>a</i>) = +∞ » n’a pas de sens. La fonction n’est pas définie en <i>a</i>, c’est sa limite qui est infinie.`),
   fig:(()=>{ const A=4, P=plane({x:[-3,3],y:[-1,10],h:280,lab:1}); P.rect(-3,A,6,6,{fill:'var(--spark)',fo:.15,c:null}).rect(-1/Math.sqrt(A),-1,2/Math.sqrt(A),11,{fill:'var(--math)',fo:.15,c:null});
     P.seg(-3,A,3,A,{c:'var(--spark)',w:1.5,dash:true}).fn(t=>1/(t*t),{from:-3,to:-.01}).fn(t=>1/(t*t),{from:.01,to:3}).text(2.9,A,'y = A',{a:'end',dy:-6,c:'var(--spark)'}).text(0,9.5,'1/x²',{dx:14,c:'var(--accent)'}); return P.svg(); })(),
   note:'Sur la figure, A = 4 et δ = 1/√4 = 0,5 : dans la bande |x| < 0,5, la courbe est au-dessus de la droite y = 4.'},
  {h:'Limites en +∞ et en −∞, limites de référence',p:`<p>On peut aussi laisser <i>x</i> grandir sans fin. Le voisinage de <i>a</i> devient un voisinage de +∞ : un intervalle ]<i>B</i> ; +∞[.</p>`
   +DEF(`${L('+∞')} f(<i>x</i>) = <i>L</i> si <b>∀ε &gt; 0, ∃<i>B</i>, ∀<i>x</i> &gt; <i>B</i>, |f(<i>x</i>) − <i>L</i>| &lt; ε</b>. &nbsp; ${L('+∞')} f(<i>x</i>) = +∞ si ∀<i>A</i>, ∃<i>B</i>, ∀<i>x</i> &gt; <i>B</i>, f(<i>x</i>) &gt; <i>A</i>. En −∞, on remplace <i>x</i> &gt; <i>B</i> par <i>x</i> &lt; <i>B</i>.`)
   +EX(`${L('+∞')} 1/<i>x</i> = 0 : pour ε &gt; 0, <i>B</i> = 1/ε convient, car <i>x</i> &gt; 1/ε donne 0 &lt; 1/<i>x</i> &lt; ε. &nbsp; ${L('+∞')} <i>x</i>² = +∞ : <i>B</i> = √<i>A</i> convient.`)
   +PROP(`<b>Limites de référence</b> (<i>n</i> ∈ ℕ*, <i>a</i> &gt; 0) :`+tab(['fonction','en +∞','en −∞','en 0'],[['<i>x</i><sup><i>n</i></sup>','+∞','+∞ si <i>n</i> pair, −∞ si impair','0'],['1/<i>x</i><sup><i>n</i></sup>','0','0','+∞ si <i>n</i> pair ; ±∞ à droite/gauche si impair'],['√<i>x</i>','+∞','—','0'],['<i>a</i><sup><i>x</i></sup> (<i>a</i> &gt; 1)','+∞','0','1'],['<i>a</i><sup><i>x</i></sup> (<i>a</i> &lt; 1)','0','+∞','1']]))
   +WHY(`Chaque ligne vient de la définition. Par exemple <i>x</i><sup><i>n</i></sup> &gt; <i>A</i> dès que <i>x</i> &gt; <i>A</i><sup>1/<i>n</i></sup>, et pour <i>a</i> &gt; 1, <i>a</i><sup><i>x</i></sup> ≥ <i>a</i><sup>⌊<i>x</i>⌋</sup> ≥ 1 + ⌊<i>x</i>⌋(<i>a</i> − 1) dépasse tout <i>A</i>. Les opérations sur les limites restent valables en ±∞, avec les mêmes formes indéterminées.`),
   fig:(()=>{ const e=.25, B=4, P=plane({x:[-1,10],y:[-.6,2.6],h:200,grid:false,lx:2,ly:1}); P.rect(B,-e,6,2*e,{fill:'var(--spark)',fo:.2,c:null}).seg(B,-.6,B,2.6,{c:'var(--math)',w:1.5,dash:true});
     P.fn(t=>1/t,{from:.4,to:10}).text(B,2.4,'x > B',{dx:6,c:'var(--math)'}).text(9.8,e,'L + ε',{a:'end',dy:-5,c:'var(--spark)',s:11}).text(3,1.2,'y = 1/x',{c:'var(--accent)'}); return P.svg(); })(),
   note:'Sur la figure, ε = 0,25 et B = 4 : au-delà de B, la courbe de 1/x reste dans la bande ]−ε ; ε[ autour de L = 0.'},
  {kind:'Méthode',h:'Forme ∞/∞ en l’infini : le terme dominant',
   p:'<b>Quand :</b> un quotient de polynômes (ou de sommes de puissances) en +∞ ou −∞ : haut et bas tendent vers l’infini, forme ∞/∞. <b>Pourquoi ça marche :</b> quand <i>x</i> est immense, <i>x</i>³ écrase <i>x</i>² et <i>x</i> : seul le terme de plus haut degré compte. En le mettant en facteur, les autres termes deviennent des <i>k</i>/<i>x</i><sup><i>p</i></sup> qui tendent vers 0. <b>Comment :</b><ol><li>mets en facteur la plus haute puissance en haut et en bas ;</li><li>simplifie les puissances de <i>x</i> ;</li><li>passe à la limite : les <i>k</i>/<i>x</i><sup><i>p</i></sup> → 0. Il reste le quotient des coefficients dominants (degrés égaux), 0 (degré du haut plus petit) ou ±∞ (degré du haut plus grand, signe à déterminer).</li></ol>',
   demo:{enonce:`Calculer ${L('+∞')} ${F('2'+x+'² − '+x+' + 3',x+'² + 5')}.`,
    etapes:[{f:'Haut → +∞ et bas → +∞ : forme ∞/∞',w:'Les règles ne concluent pas, il faut transformer.'},
     {f:`${F(x+'²(2 − 1/'+x+' + 3/'+x+'²)',x+'²(1 + 5/'+x+'²)')}`,w:'On factorise x² en haut et en bas.'},
     {f:`= ${F('2 − 1/'+x+' + 3/'+x+'²','1 + 5/'+x+'²')}`,w:'Les x² se simplifient (x ≠ 0).'},
     {f:'1/<i>x</i> → 0, 3/<i>x</i>² → 0, 5/<i>x</i>² → 0, donc le quotient → 2/1 = 2',w:'Plus d’indétermination : on applique les opérations sur les limites.'}],
    conclusion:'La limite vaut 2, le quotient des coefficients dominants. En −∞, le même calcul donne aussi 2.'},
   note:'Même recette pour ∞ − ∞ avec un polynôme : x³ − 5x² = x³(1 − 5/x) → +∞ en +∞. Le terme dominant impose son signe.'},
  {h:'Qui domine ?',p:`Calcule ${L('+∞')} ${F('3'+x+'³ − '+x,'2'+x+'³ + 5'+x+'²')}.`,lab:'limite =',ans:1.5,tol:1e-9,
   why:'On factorise x³ : (3 − 1/x²)/(2 + 5/x) → 3/2.'},
  {kind:'Méthode',h:'Forme 0/0 en un point : factoriser par (x − a)',
   p:'<b>Quand :</b> un quotient de polynômes qui donne 0/0 en <i>x</i> = <i>a</i>. <b>Pourquoi ça marche :</b> un polynôme qui s’annule en <i>a</i> se factorise par (<i>x</i> − <i>a</i>) : c’est ce facteur commun qui fabrique le 0/0. Comme la limite ne regarde que <i>x</i> ≠ <i>a</i>, on a le droit de le simplifier. <b>Comment :</b><ol><li>vérifie que c’est bien 0/0 en remplaçant ;</li><li>factorise haut et bas (identités remarquables, racines d’un trinôme, division par <i>x</i> − <i>a</i>) ;</li><li>simplifie par (<i>x</i> − <i>a</i>), puis remplace <i>x</i> par <i>a</i>. Si le bas s’annule encore seul, on est dans le cas « nombre sur 0 » : regarde les signes.</li></ol>',
   demo:{enonce:`Calculer ${L(1)} ${F(x+'² + 2'+x+' − 3',x+'² − 1')}.`,
    etapes:[{f:'En 1 : 1 + 2 − 3 = 0 et 1 − 1 = 0, forme 0/0',w:'Si ce n’était pas 0/0, on remplacerait directement.'},
     {f:`${x}² + 2${x} − 3 = (${x} − 1)(${x} + 3)`,w:'1 est racine ; l’autre racine vaut −3 car leur produit est −3.'},
     {f:`${x}² − 1 = (${x} − 1)(${x} + 1)`,w:'Différence de deux carrés.'},
     {f:`Pour ${x} ≠ 1 : ${F(x+' + 3',x+' + 1')} → ${F('4','2')} = 2`,w:'On simplifie par x − 1 ≠ 0, puis on remplace.'}],
    conclusion:'La limite vaut 2. La fonction se prolonge par continuité en 1 avec la valeur 2.'}},
  {h:'Une forme 0/0',p:`Calcule ${L(3)} ${F(x+'² − 5'+x+' + 6',x+'² − 9')}. Donne une fraction.`,lab:'limite =',ans:1/6,tol:1e-6,
   why:'x² − 5x + 6 = (x − 2)(x − 3) et x² − 9 = (x − 3)(x + 3). Pour x ≠ 3, le quotient vaut (x − 2)/(x + 3) → 1/6.'},
  {kind:'Méthode',h:'Forme 0/0 avec une racine : la quantité conjuguée',
   p:'<b>Quand :</b> le 0/0 vient d’une différence qui contient une racine, comme √(<i>x</i> + 4) − 2 ou √<i>x</i> − 3 : impossible de factoriser par (<i>x</i> − <i>a</i>) directement. <b>Pourquoi ça marche :</b> (√<i>u</i> − <i>v</i>)(√<i>u</i> + <i>v</i>) = <i>u</i> − <i>v</i>² ne contient plus de racine, et le facteur (<i>x</i> − <i>a</i>) y apparaît. La <b>quantité conjuguée</b> de √<i>u</i> − <i>v</i> est √<i>u</i> + <i>v</i>. <b>Comment :</b><ol><li>multiplie haut et bas par la quantité conjuguée (on multiplie par 1, rien ne change) ;</li><li>développe le côté qui contient la racine avec (<i>a</i> − <i>b</i>)(<i>a</i> + <i>b</i>) = <i>a</i>² − <i>b</i>² ;</li><li>simplifie par (<i>x</i> − <i>a</i>) et passe à la limite.</li></ol> Même astuce pour ∞ − ∞ avec des racines : √(<i>x</i>² + 1) − <i>x</i> = 1/(√(<i>x</i>² + 1) + <i>x</i>) → 0.',
   demo:{enonce:`Calculer ${L(9)} ${F('√'+x+' − 3',x+' − 9')}.`,
    etapes:[{f:'En 9 : √9 − 3 = 0 et 9 − 9 = 0, forme 0/0',w:'Une racine au numérateur : on pense au conjugué √x + 3.'},
     {f:`${F('(√'+x+' − 3)(√'+x+' + 3)','('+x+' − 9)(√'+x+' + 3)')}`,w:'On multiplie haut et bas par √x + 3.'},
     {f:`= ${F(x+' − 9','('+x+' − 9)(√'+x+' + 3)')} = ${F('1','√'+x+' + 3')}`,w:'(√x)² − 3² = x − 9, puis on simplifie par x − 9 ≠ 0.'},
     {f:'→ 1/(3 + 3) = 1/6',w:'On remplace x par 9 : plus d’indétermination.'}],
    conclusion:'La limite vaut 1/6.'}},
  {h:'Avec le conjugué',p:`Calcule ${L(0)} ${F('√('+x+' + 4) − 2',x)}. Donne une fraction.`,lab:'limite =',ans:.25,tol:1e-9,
   why:'On multiplie par √(x + 4) + 2 : (x + 4 − 4)/(x(√(x + 4) + 2)) = 1/(√(x + 4) + 2) → 1/4.'},
  {kind:'Récapitulatif',h:'Ce qu’il faut retenir',p:`<p>Les définitions sont toutes construites sur le même moule « pour tout voisinage de la cible, il existe un voisinage de départ ». Voici le chapitre en une page.</p>`
   +KEEP(`<ul><li><b>Limite finie en <i>a</i></b> : ∀ε &gt; 0, ∃δ &gt; 0, 0 &lt; |<i>x</i> − <i>a</i>| &lt; δ ⇒ |f(<i>x</i>) − <i>L</i>| &lt; ε. La valeur f(<i>a</i>) ne compte pas.</li><li><b>Prouver avec ε–δ</b> : majorer |f(<i>x</i>) − <i>L</i>| par <i>C</i>|<i>x</i> − <i>a</i>|, prendre δ = ε/<i>C</i>.</li><li><b>Continuité</b> en <i>a</i> ∈ <i>D</i> ⇔ lim = f(<i>a</i>). Une limite, si elle existe, est <b>unique</b>.</li><li><b>Opérations</b> : somme, produit, quotient (si <i>L</i>′ ≠ 0), composition avec une fonction continue.</li><li><b>Latérales</b> : la limite existe ⇔ limites à gauche et à droite existent et sont égales.</li><li><b>Infinie en <i>a</i></b> : ∀<i>A</i>, ∃δ, … ⇒ f(<i>x</i>) &gt; <i>A</i>. Règle « nombre sur 0⁺ ou 0⁻ ».</li><li><b>En ±∞</b> : ∀ε, ∃<i>B</i>, <i>x</i> &gt; <i>B</i> ⇒ |f(<i>x</i>) − <i>L</i>| &lt; ε. Références : <i>x</i><sup><i>n</i></sup>, 1/<i>x</i><sup><i>n</i></sup>, √<i>x</i>, <i>a</i><sup><i>x</i></sup>.</li><li><b>Formes indéterminées</b> 0/0, ∞/∞, 0 · ∞, ∞ − ∞. Les lever : <b>terme dominant</b> en l’infini, <b>factoriser par (<i>x</i> − <i>a</i>)</b> en un point, <b>quantité conjuguée</b> avec une racine.</li></ul>`)},
  {kind:'Problème',h:'Une fonction, trois endroits à examiner',
   p:`Soit f(<i>x</i>) = ${F(x+'² + '+x+' − 6',x+'² − 4')}, définie pour <i>x</i> ≠ 2 et <i>x</i> ≠ −2. On veut comprendre son comportement aux deux valeurs interdites et en +∞, puis décider où elle peut être prolongée par continuité. Commence par factoriser le numérateur et le dénominateur.`,
   fig:(()=>{ const f=t=>(t*t+t-6)/(t*t-4), P=plane({x:[-6,6],y:[-5,6],h:290,lab:2}); P.seg(-2,-5,-2,6,{c:'var(--muted)',w:1.5,dash:true}).seg(-6,1,6,1,{c:'var(--ok)',w:1.5,dash:true});
     P.fn(f,{from:-6,to:-2.05}).fn(f,{from:-1.95,to:1.99}).fn(f,{from:2.01,to:6}); hole(P,2,1.25,.15); return P.svg(); })(),
   parts:[
    {q:'a) Calcule la limite de f en 2. Donne une fraction.',lab:'limite =',ans:1.25,tol:1e-9,hint:'Forme 0/0 : factorise par (x − 2) en haut et en bas.',why:'x² + x − 6 = (x − 2)(x + 3) et x² − 4 = (x − 2)(x + 2). Pour x ≠ ±2, f(x) = (x + 3)/(x + 2) → 5/4 en 2.'},
    {q:'b) Que vaut la limite de f en −2 par la droite (<i>x</i> → −2⁺) ?',opts:['−∞','+∞','1/4','0'],ans:1,hint:'Avec la forme simplifiée (x + 3)/(x + 2), regarde le signe de x + 2 pour x > −2.',why:'(x + 3) → 1 > 0 et (x + 2) → 0⁺ pour x > −2. Un nombre positif sur 0⁺ : +∞. À gauche, on aurait −∞ : la limite en −2 n’existe pas.'},
    {q:'c) Calcule la limite de f en +∞.',lab:'limite =',ans:1,hint:'Terme dominant : x² en haut et en bas.',why:'f(x) = x²(1 + 1/x − 6/x²)/(x²(1 − 4/x²)) → 1/1 = 1. La droite y = 1 (en pointillé) est approchée par la courbe.'},
    {q:'d) En quels points f peut-elle être prolongée par continuité ?',opts:['En 2 et en −2','En −2 seulement','En 2 seulement, par f(2) = 5/4','Nulle part : f n’est pas définie en ces points'],ans:2,hint:'Un prolongement par continuité exige une limite finie.',why:'En 2, la limite est finie (5/4) : on pose f(2) = 5/4 et la fonction devient continue. En −2, la limite est infinie (et différente des deux côtés) : aucun nombre ne convient.'},
   ],
   sol:'Factorisons : f(x) = (x − 2)(x + 3)/((x − 2)(x + 2)) = (x + 3)/(x + 2) pour x ≠ ±2. En 2, cette forme donne directement 5/4 : la limite existe et vaut 5/4, le trou dans la courbe peut être rebouché par f(2) = 5/4. En −2, le numérateur tend vers 1 et le dénominateur vers 0 en changeant de signe : la limite est +∞ à droite, −∞ à gauche, et la droite x = −2 est approchée par la courbe sans être jamais touchée. En +∞ comme en −∞, les termes dominants x² donnent la limite 1. Seul le point 2 admet un prolongement par continuité.'},
  {kind:'Problème',h:'Une preuve ε–δ pour x²',
   p:'On veut démontrer avec la définition que lim<sub>x→3</sub> <i>x</i>² = 9. Contrairement au cas affine, l’écart |<i>x</i>² − 9| = |<i>x</i> − 3| · |<i>x</i> + 3| contient un facteur |<i>x</i> + 3| qui n’est pas constant : il faut le majorer. Pour cela, on décide d’abord de ne regarder que les <i>x</i> tels que |<i>x</i> − 3| &lt; 1, puis on ajuste.',
   parts:[
    {q:'a) Si |<i>x</i> − 3| &lt; 1, par quelle constante peut-on majorer |<i>x</i> + 3| (la plus petite qui marche) ?',lab:'|x + 3| <',ans:7,hint:'|x − 3| < 1 signifie 2 < x < 4. Que vaut alors x + 3 au maximum ?',why:'2 < x < 4 donne 5 < x + 3 < 7, donc |x + 3| < 7. Alors |x² − 9| < 7|x − 3|.'},
    {q:'b) Avec δ = min(1, ε/7), quel δ obtient-on pour ε = 0,14 ?',lab:'δ =',ans:.02,tol:1e-9,hint:'Calcule ε/7 et compare avec 1.',why:'ε/7 = 0,02 < 1, donc δ = 0,02. Si 0 < |x − 3| < 0,02, alors |x² − 9| < 7 · 0,02 = 0,14 = ε.'},
    {q:'c) Pourquoi prend-on δ = min(1, ε/7) et pas simplement δ = ε/7 ?',opts:['Parce que δ doit toujours être plus petit que 1 dans la définition','Parce que la majoration |x + 3| < 7 n’est garantie que si |x − 3| < 1 ; si ε est grand, ε/7 dépasse 1 et la majoration tombe','Parce que ε/7 pourrait être négatif','Pour que δ soit un nombre entier'],ans:1,hint:'La majoration de a) avait une hypothèse. Reste-t-elle vraie si δ = ε/7 > 1 ?',why:'La borne 7 vient de l’hypothèse |x − 3| < 1. Le min garantit cette hypothèse quel que soit ε. Pour ε petit, c’est ε/7 qui décide ; pour ε ≥ 7, c’est 1.'},
    {q:'d) Un élève propose δ = ε/6, en disant que |<i>x</i> + 3| est proche de 6. Que penser ?',opts:['C’est correct : près de 3, x + 3 vaut à peu près 6','C’est faux : pour ε = 3, δ = 0,5 et x = 3,5 donne |x² − 9| = 3,25 > ε','C’est faux car δ doit être plus petit que ε','C’est correct, mais seulement pour ε > 1'],ans:1,hint:'Teste avec ε = 3 et le point x = 3,5, qui est bien à moins de δ = 0,5 de 3.',why:'Pour ε = 3, δ = 0,5. Le point x = 3,5 vérifie 0 < |x − 3| < δ, mais |x² − 9| = 12,25 − 9 = 3,25 > 3. La promesse est rompue : « à peu près 6 » n’est pas une majoration.'},
   ],
   sol:'Soit ε > 0. Posons δ = min(1, ε/7). Si 0 < |x − 3| < δ, alors d’une part |x − 3| < 1, donc 2 < x < 4 et |x + 3| < 7 ; d’autre part |x − 3| < ε/7. Ainsi |x² − 9| = |x − 3| · |x + 3| < (ε/7) · 7 = ε. C’est exactement la définition : <b>lim<sub>x→3</sub> x² = 9</b>. Le min(1, ·) est indispensable : la constante 7 n’est valable que dans la fenêtre |x − 3| < 1. Et remplacer 7 par une valeur « approximative » comme 6 ne donne pas une preuve : le contre-exemple ε = 3, x = 3,5 montre que δ = ε/6 laisse passer un point dont l’image sort de la bande.'},
]},
/* ===================== 3. ASYMPTOTES, SUITES ET FONCTIONS CONTINUES ===================== */
{subj:'gred',sem:'ana',id:'gred-asymptotes-suites',h:'Asymptotes, suites et fonctions continues',p:'Les droites qu’une courbe approche sans les atteindre : verticale, horizontale, oblique. Puis le pont entre suites et fonctions : la caractérisation séquentielle de la limite et ses applications aux suites récurrentes.',steps:[
  {h:'Asymptote verticale',p:`<p>Une limite infinie en un point se voit sur le graphe : la courbe file vers le haut ou vers le bas en se collant à une droite verticale. Ici f(<i>x</i>) = ${F('2'+x,x+' − 1')}, définie pour <i>x</i> ≠ 1.</p>`
   +DEF(`La droite d’équation <b><i>x</i> = <i>a</i></b> est une <b>asymptote verticale</b> de la courbe de f si au moins une des limites latérales de f en <i>a</i> est infinie : ${L('<i>a</i>⁺')} f(<i>x</i>) = ±∞ ou ${L('<i>a</i>⁻')} f(<i>x</i>) = ±∞.`)
   +IDEA(`Quand <i>x</i> se rapproche de <i>a</i>, le point (<i>x</i> ; f(<i>x</i>)) s’éloigne à l’infini verticalement, tout en restant à distance |<i>x</i> − <i>a</i>| → 0 de la droite. La courbe et la droite se rapprochent indéfiniment sans se rencontrer, puisque f n’est pas définie en <i>a</i>.`)
   +EX(`Pour f(<i>x</i>) = 2<i>x</i>/(<i>x</i> − 1) : le numérateur tend vers 2 et le dénominateur vers 0, en étant positif à droite de 1 et négatif à gauche. Donc f → +∞ en 1⁺ et f → −∞ en 1⁻ : <b><i>x</i> = 1</b> est asymptote verticale. On la cherche aux <b>zéros du dénominateur</b> qui n’annulent pas le numérateur.`)
   +WARN(`Un zéro commun au numérateur et au dénominateur ne donne pas forcément d’asymptote : (<i>x</i>² − 1)/(<i>x</i> − 1) a une limite finie en 1, la courbe a juste un trou.`),
   fig:(()=>{ const f=t=>2*t/(t-1), P=plane({x:[-4,6],y:[-6,8],h:280,lab:2}); P.seg(1,-6,1,8,{c:'var(--bad)',w:2,dash:true}).seg(-4,2,6,2,{c:'var(--ok)',w:1.5,dash:true}); P.fn(f,{from:-4,to:.95}).fn(f,{from:1.05,to:6}); P.text(1,7.5,'x = 1',{dx:6,c:'var(--bad)'}).text(5.8,2,'y = 2',{a:'end',dy:-6,c:'var(--ok)'}); return P.svg(); })(),
   note:'La droite verte y = 2 est une asymptote horizontale, objet de l’étape suivante.'},
  {h:'Asymptote horizontale et position relative',p:`<p>À l’autre bout du graphe, quand <i>x</i> → ±∞, la courbe peut se coller à une droite horizontale.</p>`
   +DEF(`La droite <b><i>y</i> = <i>L</i></b> est une <b>asymptote horizontale</b> de la courbe de f en +∞ si ${L('+∞')} f(<i>x</i>) = <i>L</i> (de même en −∞). Les deux asymptotes horizontales, en +∞ et en −∞, peuvent être différentes.`)
   +EX(`f(<i>x</i>) = 2<i>x</i>/(<i>x</i> − 1) → 2 en +∞ et en −∞ (terme dominant) : <i>y</i> = 2 est asymptote des deux côtés. Pour g(<i>x</i>) = <i>x</i>/√(<i>x</i>² + 1), la limite vaut 1 en +∞ et −1 en −∞ : deux asymptotes différentes.`)
   +PROP(`<b>Position relative.</b> Le signe de <i>d</i>(<i>x</i>) = f(<i>x</i>) − <i>L</i> dit où est la courbe : <i>d</i> &gt; 0, la courbe est <b>au-dessus</b> de l’asymptote ; <i>d</i> &lt; 0, elle est <b>en dessous</b> ; <i>d</i> = 0, elle la coupe.`)
   +WHY(`<i>d</i>(<i>x</i>) est exactement la distance verticale signée entre le point de la courbe et le point de la droite de même abscisse. Pour f(<i>x</i>) = 2<i>x</i>/(<i>x</i> − 1), <i>d</i>(<i>x</i>) = f(<i>x</i>) − 2 = 2/(<i>x</i> − 1) : positif pour <i>x</i> &gt; 1, la courbe est au-dessus de <i>y</i> = 2 en +∞ ; négatif pour <i>x</i> &lt; 1, elle est en dessous en −∞.`)
   +WARN(`« Asymptote » ne veut pas dire « jamais touchée ». La courbe de (sin <i>x</i>)/<i>x</i> coupe son asymptote <i>y</i> = 0 une infinité de fois. Seule compte la limite de l’écart.`)},
  {h:'Asymptote oblique',p:`<p>Quand f(<i>x</i>) → ±∞ en +∞, il n’y a pas d’asymptote horizontale. Mais la courbe peut quand même se coller à une droite, inclinée cette fois. Ici f(<i>x</i>) = ${F(x+'² + 1',x+' − 1')}.</p>`
   +DEF(`La droite <b><i>y</i> = <i>mx</i> + <i>p</i></b> (<i>m</i> ≠ 0) est une <b>asymptote oblique</b> de la courbe de f en +∞ si <b>${L('+∞')} [f(<i>x</i>) − (<i>mx</i> + <i>p</i>)] = 0</b>. Même définition en −∞.`)
   +IDEA(`La définition dit : l’écart vertical entre la courbe et la droite tend vers 0. C’est la même idée que pour l’asymptote horizontale, qui est le cas <i>m</i> = 0. Quand f s’écrit <b>f(<i>x</i>) = <i>mx</i> + <i>p</i> + <i>r</i>(<i>x</i>)</b> avec <i>r</i>(<i>x</i>) → 0, la droite <i>y</i> = <i>mx</i> + <i>p</i> est asymptote et <i>r</i>(<i>x</i>) donne la position relative.`)
   +EX(`${F(x+'² + 1',x+' − 1')} = <i>x</i> + 1 + ${F('2',x+' − 1')} (vérifie : (<i>x</i> + 1)(<i>x</i> − 1) + 2 = <i>x</i>² + 1). Comme 2/(<i>x</i> − 1) → 0 en ±∞, la droite <b><i>y</i> = <i>x</i> + 1</b> est asymptote oblique des deux côtés. La figure montre la courbe, la droite, et l’écart <i>r</i>(<i>x</i>) = 2/(<i>x</i> − 1) qui fond quand <i>x</i> grandit.`)
   +RAP(`Pour une fraction rationnelle dont le numérateur a un degré de plus que le dénominateur, la <b>division euclidienne</b> des polynômes donne directement l’écriture <i>mx</i> + <i>p</i> + reste/dénominateur.`),
   fig:(()=>{ const f=t=>(t*t+1)/(t-1), P=plane({x:[-5,7],y:[-6,10],h:300,lab:2}); P.fn(t=>t+1,{c:'var(--ok)',w:1.5,dash:true}).seg(1,-6,1,10,{c:'var(--muted)',w:1,dash:true}); P.fn(f,{from:-5,to:.9}).fn(f,{from:1.1,to:7});
     [3,5].forEach(t=>P.seg(t,t+1,t,f(t),{c:'var(--spark)',w:3})); P.text(6.8,7.8,'y = x + 1',{a:'end',c:'var(--ok)'}).text(3.2,4.5,'r(3) = 1',{c:'var(--spark)'}).text(5.2,6.2,'r(5) = 0,5',{c:'var(--spark)'}); return P.svg(); })()},
  {kind:'Méthode',h:'Trouver l’asymptote oblique : m puis p',
   p:`<b>Quand :</b> f(<i>x</i>) → ±∞ en +∞ (ou −∞) et on soupçonne une asymptote oblique, typiquement une fraction rationnelle dont le numérateur a un degré de plus que le dénominateur. <b>Pourquoi ça marche :</b> si f(<i>x</i>) − <i>mx</i> − <i>p</i> → 0, alors en divisant par <i>x</i> : f(<i>x</i>)/<i>x</i> = <i>m</i> + <i>p</i>/<i>x</i> + (f(<i>x</i>) − <i>mx</i> − <i>p</i>)/<i>x</i> → <i>m</i>. Puis f(<i>x</i>) − <i>mx</i> = <i>p</i> + (f(<i>x</i>) − <i>mx</i> − <i>p</i>) → <i>p</i>. <b>Comment :</b><ol><li><b><i>m</i> = ${L('+∞')} f(<i>x</i>)/<i>x</i></b> (doit être un réel non nul) ;</li><li><b><i>p</i> = ${L('+∞')} [f(<i>x</i>) − <i>mx</i>]</b> (doit être un réel) ;</li><li>conclus : <i>y</i> = <i>mx</i> + <i>p</i> est asymptote, puis étudie le signe de f(<i>x</i>) − (<i>mx</i> + <i>p</i>) pour la position. Pour une fraction rationnelle, la division euclidienne donne tout d’un coup.</li></ol>`,
   demo:{enonce:`Asymptote oblique en +∞ de f(<i>x</i>) = ${F('2'+x+'² − 3'+x+' + 1',x+' + 1')}.`,
    etapes:[{f:`f(<i>x</i>)/<i>x</i> = ${F('2'+x+'² − 3'+x+' + 1',x+'² + '+x)} → 2, donc <i>m</i> = 2`,w:'Terme dominant : 2x²/x² = 2.'},
     {f:`f(<i>x</i>) − 2<i>x</i> = ${F('2'+x+'² − 3'+x+' + 1 − 2'+x+'('+x+' + 1)',x+' + 1')} = ${F('−5'+x+' + 1',x+' + 1')} → −5, donc <i>p</i> = −5`,w:'On met au même dénominateur, puis terme dominant : −5x/x.'},
     {f:`f(<i>x</i>) − (2<i>x</i> − 5) = ${F('−5'+x+' + 1 + 5('+x+' + 1)',x+' + 1')} = ${F('6',x+' + 1')}`,w:'L’écart à la droite : il tend bien vers 0, et son signe donne la position.'}],
    conclusion:'<i>y</i> = 2<i>x</i> − 5 est asymptote oblique en +∞ (et en −∞). L’écart 6/(<i>x</i> + 1) est positif pour <i>x</i> &gt; −1 : la courbe est au-dessus de la droite en +∞, en dessous en −∞. Contrôle par division : 2<i>x</i>² − 3<i>x</i> + 1 = (<i>x</i> + 1)(2<i>x</i> − 5) + 6.'},
   note:'Si m = 0, c’est une asymptote horizontale. Si f(x)/x → ±∞ ou si p n’existe pas (par exemple f(x) = x + √x), il n’y a pas d’asymptote oblique : on parle de branche parabolique.'},
  {kind:'Pratique',h:'Ajuste la droite',p:`La courbe est celle de f(<i>x</i>) = ${F(x+'² + 1',x+' − 1')}. Règle <i>m</i> et <i>p</i> pour que la droite <i>y</i> = <i>mx</i> + <i>p</i> soit son asymptote oblique : l’écart f(<i>x</i>) − (<i>mx</i> + <i>p</i>), affiché pour <i>x</i> = 50, doit devenir quasi nul.`,
   params:[{id:'m',l:'Pente m',min:-1,max:3,step:.5,v:2},{id:'p',l:'Ordonnée p',min:-3,max:3,step:.5,v:0}],
   draw:v=>{ const f=t=>(t*t+1)/(t-1), P=plane({x:[-5,7],y:[-6,10],h:300,lab:2}); P.fn(t=>v.m*t+v.p,{c:'var(--ok)',w:2,dash:true}); P.fn(f,{from:-5,to:.9}).fn(f,{from:1.1,to:7}); P.seg(6,6*v.m+v.p,6,f(6),{c:'var(--spark)',w:3}); return P.svg(); },
   info:v=>{ const f=t=>(t*t+1)/(t-1); return `Écart en x = 50 : f(50) − (50m + p) = ${fmt(f(50)-(50*v.m+v.p),3)}. ${v.m===1&&v.p===1?'Il tend vers 0 : c’est l’asymptote.':'Il ne tend pas vers 0.'}`; },
   ok:v=>v.m===1&&v.p===1,
   why:'f(x)/x = (x² + 1)/(x² − x) → 1 = m, puis f(x) − x = (x + 1)/(x − 1) → 1 = p. L’asymptote est y = x + 1, et l’écart 2/(x − 1) tend vers 0.'},
  {h:'Lis la position relative',p:`Que vaut l’ordonnée à l’origine <i>p</i> de l’asymptote oblique de f(<i>x</i>) = ${F('3'+x+'² + 2'+x+' − 1',x)} ?`,lab:'p =',ans:2,
   why:'f(x) = 3x + 2 − 1/x. Comme 1/x → 0, l’asymptote est y = 3x + 2 : m = 3 et p = 2.'},
  {h:'Au-dessus ou en dessous ?',p:`Soit f(<i>x</i>) = ${F(x+'² + '+x+' + 3',x)}. Par rapport à son asymptote oblique, où se trouve la courbe ?`,
   opts:['Au-dessus en +∞ et en −∞','En dessous en +∞ et en −∞','Au-dessus en +∞, en dessous en −∞','En dessous en +∞, au-dessus en −∞'],ans:2,
   why:'f(x) = x + 1 + 3/x : l’asymptote est y = x + 1 et l’écart vaut 3/x. Il est positif pour x > 0 (courbe au-dessus en +∞) et négatif pour x < 0 (en dessous en −∞).'},
  {h:'Limite d’une fonction et suites',p:`<p>Les suites ont déjà toute une théorie de la limite. Peut-on s’en servir pour les fonctions ? Oui : approcher <i>a</i> par une suite (<i>u<sub>n</sub></i>) et regarder la suite des images f(<i>u<sub>n</sub></i>).</p>`
   +THM(`<b>Caractérisation séquentielle.</b> ${L('<i>a</i>')} f(<i>x</i>) = <i>L</i> si et seulement si, pour <b>toute</b> suite (<i>u<sub>n</sub></i>) de points de <i>D</i> ∖ {<i>a</i>} qui converge vers <i>a</i>, la suite (f(<i>u<sub>n</sub></i>)) converge vers <i>L</i>. L’énoncé reste vrai avec <i>a</i> ou <i>L</i> infinis.`)
   +WHY(`<b>Sens direct.</b> Soit ε &gt; 0. La limite fournit δ tel que 0 &lt; |<i>x</i> − <i>a</i>| &lt; δ ⇒ |f(<i>x</i>) − <i>L</i>| &lt; ε. Comme <i>u<sub>n</sub></i> → <i>a</i> avec <i>u<sub>n</sub></i> ≠ <i>a</i>, il existe <i>N</i> tel que 0 &lt; |<i>u<sub>n</sub></i> − <i>a</i>| &lt; δ pour <i>n</i> ≥ <i>N</i>. Alors |f(<i>u<sub>n</sub></i>) − <i>L</i>| &lt; ε pour ces <i>n</i> : c’est la définition de f(<i>u<sub>n</sub></i>) → <i>L</i>. <b>Réciproque</b> (idée) : si f n’avait pas <i>L</i> pour limite, un certain ε mettrait en échec tous les δ, en particulier δ = 1/<i>n</i> ; on choisirait un <i>u<sub>n</sub></i> avec |<i>u<sub>n</sub></i> − <i>a</i>| &lt; 1/<i>n</i> et |f(<i>u<sub>n</sub></i>) − <i>L</i>| ≥ ε, ce qui donnerait une suite <i>u<sub>n</sub></i> → <i>a</i> dont les images ne tendent pas vers <i>L</i>.`)
   +EX(`Avec f(<i>x</i>) = <i>x</i>² et <i>u<sub>n</sub></i> = 1 + 1/<i>n</i> → 1 : f(<i>u<sub>n</sub></i>) = (1 + 1/<i>n</i>)² = 1 + 2/<i>n</i> + 1/<i>n</i>² → 1 = f(1), comme prévu.`)
   +WARN(`Le mot important est <b>toute</b>. Une seule suite qui marche ne prouve rien ; mais une seule suite qui échoue, ou deux suites qui donnent des limites différentes, suffisent à prouver que la limite <b>n’existe pas</b>.`)},
  {h:'Continuité et suites : échanger f et lim',p:`<p>Appliquée à une fonction continue, la caractérisation séquentielle donne une règle de calcul qu’on utilise sans arrêt.</p>`
   +PROP(`f est <b>continue en <i>a</i></b> si et seulement si pour toute suite (<i>u<sub>n</sub></i>) de <i>D</i> qui converge vers <i>a</i>, <b>f(<i>u<sub>n</sub></i>) → f(<i>a</i>)</b>. Autrement dit : <b>lim f(<i>u<sub>n</sub></i>) = f(lim <i>u<sub>n</sub></i>)</b>. On peut faire passer la limite à l’intérieur d’une fonction continue.`)
   +WHY(`C’est le théorème précédent avec <i>L</i> = f(<i>a</i>), et la restriction <i>u<sub>n</sub></i> ≠ <i>a</i> devient inutile : si <i>u<sub>n</sub></i> = <i>a</i>, alors f(<i>u<sub>n</sub></i>) = f(<i>a</i>) est déjà à la bonne place.`)
   +EX(`<i>u<sub>n</sub></i> = √(4 + 1/<i>n</i>) : comme 4 + 1/<i>n</i> → 4 et que la racine carrée est continue en 4, <i>u<sub>n</sub></i> → √4 = 2. &nbsp; <i>v<sub>n</sub></i> = (2 + 3/<i>n</i>)³ → 2³ = 8, car <i>x</i> ↦ <i>x</i>³ est continue. &nbsp; <i>w<sub>n</sub></i> = 2<sup>1/<i>n</i></sup> → 2⁰ = 1, car exp<sub>2</sub> est continue en 0.`)
   +WARN(`Sans continuité, l’échange est faux. La fonction <i>E</i> « partie entière » (le plus grand entier ≤ <i>x</i>) n’est pas continue en 1 : avec <i>u<sub>n</sub></i> = 1 − 1/<i>n</i> → 1, on a <i>E</i>(<i>u<sub>n</sub></i>) = 0 pour tout <i>n</i>, qui ne tend pas vers <i>E</i>(1) = 1.`)},
  {h:'Passe à la limite dans la fonction',p:`Calcule la limite de <i>u<sub>n</sub></i> = ${F('(3'+n+' + 1)²','('+n+' + 1)²')}.`,lab:'limite =',ans:9,
   why:'u_n = ((3n + 1)/(n + 1))² et (3n + 1)/(n + 1) → 3. Comme x ↦ x² est continue en 3, u_n → 3² = 9.'},
  {kind:'Méthode',h:'Montrer qu’une limite n’existe pas avec deux suites',
   p:'<b>Quand :</b> on soupçonne qu’une fonction oscille ou saute près de <i>a</i> (ou en l’infini), comme sin(1/<i>x</i>) en 0, <i>x</i>/|<i>x</i>| en 0, sin <i>x</i> en +∞. <b>Pourquoi ça marche :</b> si la limite existait, toute suite tendant vers <i>a</i> donnerait des images tendant vers cette même limite. Deux suites avec des limites d’images différentes contredisent l’unicité. <b>Comment :</b><ol><li>choisis une suite (<i>u<sub>n</sub></i>) → <i>a</i> sur laquelle f est facile à calculer, note la limite de f(<i>u<sub>n</sub></i>) ;</li><li>choisis une autre suite (<i>v<sub>n</sub></i>) → <i>a</i> qui donne une autre valeur ;</li><li>conclus : les deux limites diffèrent, f n’a pas de limite en <i>a</i>. Une seule suite dont les images n’ont pas de limite marche aussi.</li></ol>',
   demo:{enonce:'Montrer que f(<i>x</i>) = sin(1/<i>x</i>) n’a pas de limite en 0.',
    etapes:[{f:'<i>u<sub>n</sub></i> = 1/(2π<i>n</i>) → 0 et f(<i>u<sub>n</sub></i>) = sin(2π<i>n</i>) = 0 pour tout <i>n</i>, donc f(<i>u<sub>n</sub></i>) → 0',w:'On choisit u_n pour que 1/u_n soit un angle où le sinus est connu.'},
     {f:'<i>v<sub>n</sub></i> = 1/(π/2 + 2π<i>n</i>) → 0 et f(<i>v<sub>n</sub></i>) = sin(π/2 + 2π<i>n</i>) = 1, donc f(<i>v<sub>n</sub></i>) → 1',w:'Une autre suite, qui vise les sommets de la courbe.'},
     {f:'0 ≠ 1 : si f avait une limite L en 0, on aurait L = 0 et L = 1',w:'Contradiction avec l’unicité de la limite.'}],
    conclusion:'sin(1/<i>x</i>) n’a pas de limite en 0 : près de 0, la courbe oscille une infinité de fois entre −1 et 1 (figure).'},
   fig:(()=>{ const P=plane({x:[-.4,.4],y:[-1.3,1.3],h:220,step:.1,lx:.2,ly:1}); P.fn(t=>Math.sin(1/t),{from:-.4,to:-.004,n:1500,w:2}).fn(t=>Math.sin(1/t),{from:.004,to:.4,n:1500,w:2}); for(let k=1;k<=3;k++) P.dot(1/(2*Math.PI*k),0,{r:4,c:'var(--math)'}).dot(1/(Math.PI/2+2*Math.PI*k),1,{r:4,c:'var(--spark)'}); return P.svg(); })(),
   note:'Points bleus : u_n (images 0). Points orange : v_n (images 1). Les deux familles s’accumulent en 0.'},
  {h:'Choisis les deux suites',p:`Pour prouver que g(<i>x</i>) = ${x}/|${x}| n’a pas de limite en 0, quel couple de suites convient ?`,
   opts:['<i>u<sub>n</sub></i> = 1/<i>n</i> et <i>v<sub>n</sub></i> = 1/(2<i>n</i>)','<i>u<sub>n</sub></i> = 1/<i>n</i> et <i>v<sub>n</sub></i> = −1/<i>n</i>','<i>u<sub>n</sub></i> = <i>n</i> et <i>v<sub>n</sub></i> = −<i>n</i>','<i>u<sub>n</sub></i> = 1/<i>n</i> et <i>v<sub>n</sub></i> = 1 + 1/<i>n</i>'],ans:1,
   why:'Il faut deux suites qui tendent vers 0 avec des images de limites différentes : g(1/n) = 1 et g(−1/n) = −1. Le premier couple donne deux fois 1 ; le troisième ne tend pas vers 0 ; dans le dernier, v_n tend vers 1.'},
  {h:'Suites récurrentes et point fixe',p:`<p>Beaucoup de suites sont définies par <i>u</i><sub><i>n</i>+1</sub> = f(<i>u<sub>n</sub></i>) : chaque terme est l’image du précédent. Si une telle suite converge, vers quoi peut-elle tendre ?</p>`
   +THM(`Soit (<i>u<sub>n</sub></i>) définie par <i>u</i><sub><i>n</i>+1</sub> = f(<i>u<sub>n</sub></i>). Si <i>u<sub>n</sub></i> → ℓ et si <b>f est continue en ℓ</b>, alors <b>f(ℓ) = ℓ</b> : la limite est un <b>point fixe</b> de f.`)
   +WHY(`La suite (<i>u</i><sub><i>n</i>+1</sub>) est la même suite décalée d’un rang : elle tend aussi vers ℓ. Mais <i>u</i><sub><i>n</i>+1</sub> = f(<i>u<sub>n</sub></i>), et par continuité de f en ℓ, f(<i>u<sub>n</sub></i>) → f(ℓ). Une suite n’a qu’une limite, donc f(ℓ) = ℓ.`)
   +IDEA(`Graphiquement, on part de <i>u</i>₀ sur l’axe, on monte sur la courbe de f pour lire <i>u</i>₁, on revient sur la diagonale <i>y</i> = <i>x</i> pour reporter <i>u</i>₁ en abscisse, et on recommence. L’escalier se coince là où la courbe coupe la diagonale : un point fixe. Ici f(<i>x</i>) = √(2 + <i>x</i>) et <i>u</i>₀ = 0 ; avance le curseur.`)
   +EX(`Points fixes de f(<i>x</i>) = √(2 + <i>x</i>) : ℓ = √(2 + ℓ) ⇒ ℓ² = 2 + ℓ ⇒ ℓ² − ℓ − 2 = 0 ⇒ ℓ = 2 ou ℓ = −1. Comme ℓ ≥ 0 (c’est une racine carrée), seule ℓ = 2 convient : si la suite converge, c’est vers 2.`)
   +WARN(`Le théorème dit « <b>si</b> la suite converge ». Il ne prouve pas la convergence : <i>u</i><sub><i>n</i>+1</sub> = 2<i>u<sub>n</sub></i> a 0 pour unique point fixe, mais avec <i>u</i>₀ = 1 la suite file vers +∞. La convergence se démontre à part (suite monotone et bornée, par exemple).`),
   params:[{id:'k',l:'Nombre d’étapes',min:0,max:8,v:0}],
   draw:v=>{ const f=t=>Math.sqrt(2+t), P=plane({x:[-.5,3],y:[-.5,3],h:300,step:.5,lab:1}); P.fn(t=>t,{c:'var(--muted)',w:1.5,dash:true}).fn(f,{from:-.5,to:3}); P.dot(2,2,{r:5,c:'var(--ok)',l:'(2 ; 2)'});
     let u=0; P.dot(u,0,{r:5,c:'var(--spark)',l:'u₀',dy:16});
     for(let i=0;i<v.k;i++){ const w=f(u); P.seg(u,i?u:0,u,w,{c:'var(--spark)',w:2}).seg(u,w,w,w,{c:'var(--spark)',w:2}); u=w; }
     if(v.k) P.dot(u,u,{r:5,c:'var(--spark)'}); return P.svg(); },
   info:v=>{ let u=0; for(let i=0;i<v.k;i++) u=Math.sqrt(2+u); return `u<sub>${v.k}</sub> = ${fmt(u,5)} ; écart à 2 : ${fmt(2-u,5)}.`; }},
  {kind:'Méthode',h:'Trouver la limite d’une suite récurrente',
   p:'<b>Quand :</b> <i>u</i><sub><i>n</i>+1</sub> = f(<i>u<sub>n</sub></i>) avec f continue, et on demande la limite. <b>Pourquoi ça marche :</b> le théorème du point fixe réduit les candidats aux solutions de f(ℓ) = ℓ ; la convergence, elle, vient d’un argument séparé. <b>Comment :</b><ol><li><b>Convergence</b> : montre que la suite est monotone et bornée (souvent par récurrence : un encadrement qui se transmet de <i>u<sub>n</sub></i> à <i>u</i><sub><i>n</i>+1</sub>), ou admets-la si l’énoncé le dit ;</li><li><b>Candidats</b> : résous f(ℓ) = ℓ ;</li><li><b>Choix</b> : élimine les candidats incompatibles avec l’encadrement ou la monotonie (signe, position par rapport à <i>u</i>₀).</li></ol>',
   demo:{enonce:`<i>u</i>₀ = 0 et <i>u</i><sub><i>n</i>+1</sub> = ${F('<i>u<sub>n</sub></i>² + 2','3')}. On admet que la suite est croissante et majorée par 1. Trouver sa limite.`,
    etapes:[{f:'Croissante et majorée : la suite converge vers un réel ℓ, avec 0 ≤ ℓ ≤ 1.',w:'Le théorème des suites monotones. Les termes restent dans [0 ; 1], donc la limite aussi.'},
     {f:'f(<i>x</i>) = (<i>x</i>² + 2)/3 est continue (polynôme), donc f(ℓ) = ℓ.',w:'Théorème du point fixe.'},
     {f:'(ℓ² + 2)/3 = ℓ ⇔ ℓ² − 3ℓ + 2 = 0 ⇔ (ℓ − 1)(ℓ − 2) = 0 ⇔ ℓ = 1 ou ℓ = 2',w:'On résout l’équation du point fixe.'},
     {f:'ℓ ≤ 1 exclut 2. Donc ℓ = 1.',w:'Le majorant tranche entre les deux candidats.'}],
    conclusion:'La suite tend vers 1. Numériquement : <i>u</i>₁ ≈ 0,667, <i>u</i>₂ ≈ 0,815, <i>u</i>₃ ≈ 0,888, <i>u</i>₈ ≈ 0,987.'},
   note:'Avec u₀ = 3, la même formule donne une suite croissante non majorée (3 → 11/3 → …), qui diverge : le point fixe 2 n’attire rien. Le choix de u₀ compte.'},
  {h:'Un point fixe à choisir',p:'<i>u</i>₀ = 1 et <i>u</i><sub><i>n</i>+1</sub> = √(6 + <i>u<sub>n</sub></i>). On admet que la suite converge. Quelle est sa limite ?',lab:'limite =',ans:3,
   why:'f(x) = √(6 + x) est continue, donc ℓ = √(6 + ℓ), soit ℓ² − ℓ − 6 = 0 : ℓ = 3 ou ℓ = −2. Une racine carrée est positive, donc ℓ = 3.'},
  {kind:'Récapitulatif',h:'Ce qu’il faut retenir',p:`<p>Deux thèmes : les droites qu’une courbe approche, et le dictionnaire entre suites et fonctions.</p>`
   +KEEP(`<ul><li><b>Asymptote verticale</b> <i>x</i> = <i>a</i> : une limite latérale infinie en <i>a</i>. À chercher aux zéros du dénominateur.</li><li><b>Asymptote horizontale</b> <i>y</i> = <i>L</i> : f → <i>L</i> en ±∞ (les deux côtés peuvent différer).</li><li><b>Asymptote oblique</b> <i>y</i> = <i>mx</i> + <i>p</i> : f(<i>x</i>) − (<i>mx</i> + <i>p</i>) → 0. Recette : <i>m</i> = lim f(<i>x</i>)/<i>x</i>, <i>p</i> = lim [f(<i>x</i>) − <i>mx</i>] ; ou division euclidienne.</li><li><b>Position relative</b> : signe de l’écart f(<i>x</i>) − (<i>mx</i> + <i>p</i>).</li><li><b>Caractérisation séquentielle</b> : lim f = <i>L</i> en <i>a</i> ⇔ pour toute suite <i>u<sub>n</sub></i> → <i>a</i> (<i>u<sub>n</sub></i> ≠ <i>a</i>), f(<i>u<sub>n</sub></i>) → <i>L</i>.</li><li><b>f continue</b> ⇔ lim f(<i>u<sub>n</sub></i>) = f(lim <i>u<sub>n</sub></i>) : la limite passe dans la fonction.</li><li><b>Pas de limite</b> : deux suites → <i>a</i> avec des images de limites différentes (sin(1/<i>x</i>) en 0).</li><li><b>Point fixe</b> : si <i>u</i><sub><i>n</i>+1</sub> = f(<i>u<sub>n</sub></i>), <i>u<sub>n</sub></i> → ℓ et f continue en ℓ, alors f(ℓ) = ℓ. La convergence se prouve à part.</li></ul>`)},
  {kind:'Problème',h:'Toutes les asymptotes d’une courbe',
   p:`Soit f(<i>x</i>) = ${F(x+'² − 3'+x+' + 5',x+' − 2')}, définie pour <i>x</i> ≠ 2. On veut trouver toutes ses asymptotes et la position de la courbe par rapport à l’asymptote oblique. La division euclidienne donne <i>x</i>² − 3<i>x</i> + 5 = (<i>x</i> − 2)(<i>x</i> − 1) + 3 : vérifie-la avant de commencer.`,
   fig:(()=>{ const f=t=>(t*t-3*t+5)/(t-2), P=plane({x:[-4,8],y:[-8,10],h:300,lab:2}); P.seg(2,-8,2,10,{c:'var(--bad)',w:1.5,dash:true}).fn(t=>t-1,{c:'var(--ok)',w:1.5,dash:true}); P.fn(f,{from:-4,to:1.9}).fn(f,{from:2.1,to:8}); return P.svg(); })(),
   parts:[
    {q:'a) Quelle est l’équation de l’asymptote verticale ? Donne la valeur de <i>a</i> dans <i>x</i> = <i>a</i>.',lab:'a =',ans:2,hint:'Où le dénominateur s’annule-t-il sans que le numérateur s’annule ?',why:'En 2, le dénominateur tend vers 0 et le numérateur vers 4 − 6 + 5 = 3 ≠ 0. Les limites latérales sont infinies (+∞ à droite, −∞ à gauche) : x = 2 est asymptote verticale.'},
    {q:'b) Quelle est la pente <i>m</i> de l’asymptote oblique ?',lab:'m =',ans:1,hint:'m = lim f(x)/x, ou lis le quotient de la division euclidienne.',why:'f(x) = x − 1 + 3/(x − 2), donc f(x)/x → 1. La pente est m = 1.'},
    {q:'c) Quelle est son ordonnée à l’origine <i>p</i> ?',lab:'p =',ans:-1,hint:'p = lim [f(x) − x].',why:'f(x) − x = −1 + 3/(x − 2) → −1. L’asymptote oblique est y = x − 1.'},
    {q:'d) Où est la courbe par rapport à la droite <i>y</i> = <i>x</i> − 1 ?',opts:['Au-dessus partout','Au-dessus pour x > 2, en dessous pour x < 2','En dessous pour x > 2, au-dessus pour x < 2','La courbe coupe la droite en x = 2'],ans:1,hint:'Étudie le signe de l’écart f(x) − (x − 1).',why:'f(x) − (x − 1) = 3/(x − 2) : positif si x > 2 (au-dessus), négatif si x < 2 (en dessous). L’écart ne s’annule jamais : la courbe ne coupe pas son asymptote.'},
   ],
   sol:'La division x² − 3x + 5 = (x − 2)(x − 1) + 3 donne f(x) = x − 1 + 3/(x − 2). En 2, le terme 3/(x − 2) tend vers +∞ à droite et −∞ à gauche : <b>x = 2</b> est asymptote verticale. En ±∞, 3/(x − 2) → 0 : la droite <b>y = x − 1</b> est asymptote oblique des deux côtés (on retrouve m = lim f(x)/x = 1 et p = lim (f(x) − x) = −1). L’écart 3/(x − 2) est positif pour x > 2 et négatif pour x < 2 : la courbe est au-dessus de l’asymptote à droite, en dessous à gauche. Pas d’asymptote horizontale, puisque f → ±∞ en ±∞.'},
  {kind:'Problème',h:'La méthode de Héron pour √3',
   p:'Pour calculer √3 sans calculatrice, les Babyloniens utilisaient la suite <i>u</i>₀ = 3 et <i>u</i><sub><i>n</i>+1</sub> = ½(<i>u<sub>n</sub></i> + 3/<i>u<sub>n</sub></i>) : on fait la moyenne entre un nombre et 3 divisé par ce nombre. On admet que la suite est décroissante à partir de <i>u</i>₁ et minorée par √3, donc convergente. On veut identifier sa limite et mesurer la vitesse de convergence.',
   params:[{id:'k',l:'Nombre d’étapes',min:0,max:4,v:0}],
   draw:v=>{ const f=t=>(t+3/t)/2, P=plane({x:[0,3.5],y:[0,3.5],h:300,step:.5,lab:1}); P.fn(t=>t,{c:'var(--muted)',w:1.5,dash:true}).fn(f,{from:.9,to:3.5}); P.dot(Math.sqrt(3),Math.sqrt(3),{r:5,c:'var(--ok)',l:'(√3 ; √3)',dx:10,dy:14});
     let u=3; P.dot(u,0,{r:5,c:'var(--spark)',l:'u₀',dy:-10}); for(let i=0;i<v.k;i++){ const w=f(u); P.seg(u,i?u:0,u,w,{c:'var(--spark)',w:2}).seg(u,w,w,w,{c:'var(--spark)',w:2}); u=w; } if(v.k) P.dot(u,u,{r:5,c:'var(--spark)'}); return P.svg(); },
   info:v=>{ let u=3; for(let i=0;i<v.k;i++) u=(u+3/u)/2; return `u<sub>${v.k}</sub> = ${fmt(u,7)} ; u<sub>${v.k}</sub> − √3 ≈ ${fmt(u-Math.sqrt(3),7)}`; },
   parts:[
    {q:'a) Calcule <i>u</i>₁.',lab:'u₁ =',ans:2,hint:'Moyenne de 3 et de 3/3.',why:'u₁ = ½(3 + 3/3) = ½(3 + 1) = 2.'},
    {q:'b) Si la suite converge vers ℓ &gt; 0, quelle équation ℓ vérifie-t-elle ?',opts:['ℓ = 3','ℓ² = 3','2ℓ = 3/ℓ + 1','ℓ² + 3 = 0'],ans:1,hint:'Écris f(ℓ) = ℓ avec f(x) = ½(x + 3/x), puis multiplie par 2ℓ.',why:'f est continue sur ]0 ; +∞[, donc ℓ = ½(ℓ + 3/ℓ). En multipliant par 2ℓ : 2ℓ² = ℓ² + 3, soit ℓ² = 3.'},
    {q:'c) Quelle est la limite de la suite ? Donne 4 décimales.',lab:'ℓ ≈',ans:Math.sqrt(3),tol:6e-5,hint:'Deux solutions à ℓ² = 3 ; une seule est compatible avec les termes de la suite.',why:'ℓ² = 3 donne ℓ = √3 ou ℓ = −√3. Tous les termes sont positifs (et même ≥ √3), donc ℓ = √3 ≈ 1,7321.'},
    {q:'d) Calcule <i>u</i>₂. Donne la valeur exacte en décimal.',lab:'u₂ =',ans:1.75,tol:1e-9,hint:'Moyenne de 2 et de 3/2.',why:'u₂ = ½(2 + 3/2) = ½ · 7/2 = 7/4 = 1,75. L’erreur n’est déjà plus que 0,018 ; u₃ = 97/56 ≈ 1,732143 est juste à 10⁻⁴ près.'},
   ],
   sol:'u₁ = ½(3 + 1) = 2, u₂ = ½(2 + 3/2) = 7/4 = 1,75, u₃ = ½(7/4 + 12/7) = 97/56 ≈ 1,73214. La suite converge (décroissante, minorée) vers un réel ℓ ≥ √3 > 0. La fonction f(x) = ½(x + 3/x) est continue en ℓ, donc f(ℓ) = ℓ, c’est-à-dire ℓ² = 3. Les termes étant positifs, <b>ℓ = √3 ≈ 1,7320508</b>. La convergence est remarquablement rapide : l’erreur passe de 0,27 à 0,018 puis à 0,00009, à peu près le carré de la précédente à chaque étape. C’est l’ancêtre de la méthode de Newton.'},
]},
/* ===================== 4. LA DÉRIVÉE : DÉFINITION ET INTERPRÉTATION ===================== */
{subj:'gred',sem:'ana',id:'gred-derivee-def',h:'La dérivée : définition et interprétation',p:'De la vitesse instantanée à la pente d’une courbe : le taux d’accroissement, le nombre dérivé comme limite, la tangente, le lien avec la continuité, les premières dérivées calculées à la main et l’approximation affine.',steps:[
  {h:'Quelle est la vitesse à l’instant t = 1 ?',p:`<p>Une bille lâchée sans vitesse parcourt <i>s</i>(<i>t</i>) = 5<i>t</i>² mètres en <i>t</i> secondes. Sa <b>vitesse moyenne</b> entre les instants 1 et 1 + <i>h</i> est la distance parcourue divisée par la durée : ${F('<i>s</i>(1 + <i>h</i>) − <i>s</i>(1)','<i>h</i>')}. Mais que vaut sa vitesse <b>à l’instant</b> <i>t</i> = 1 exactement ? Sur une durée nulle, la bille ne parcourt rien : 0/0, le calcul direct est impossible.</p>`
   +IDEA(`On ne peut pas mesurer une vitesse instantanée, mais on peut l’<b>approcher</b> : des vitesses moyennes sur des durées de plus en plus courtes. Ici ${F('5(1 + <i>h</i>)² − 5','<i>h</i>')} = ${F('10<i>h</i> + 5<i>h</i>²','<i>h</i>')} = 10 + 5<i>h</i>. Quand <i>h</i> → 0, ce nombre tend vers 10 : la vitesse instantanée à <i>t</i> = 1 est 10 m/s. Réduis <i>h</i> avec le curseur : la sécante (orange) pivote vers une position limite, la tangente (vert).`)
   +`<p>La même question se pose pour n’importe quelle courbe : quelle est sa <b>pente</b> en un point ? Une droite a une pente, une parabole n’en a pas… sauf si on regarde d’assez près. Ce chapitre construit cet outil, la <b>dérivée</b>, à partir de la limite.</p>`,
   params:[{id:'h',l:'Durée h',min:.05,max:1.5,step:.05,v:1.5}],
   draw:v=>{ const s=t=>5*t*t, P=plane({x:[-.3,3],y:[-3,30],h:300,step:5,lx:1,ly:10}); P.fn(s,{from:0,to:3}); P.fn(t=>5+10*(t-1),{c:'var(--ok)',w:2,dash:true}).fn(t=>5+(10+5*v.h)*(t-1),{c:'var(--spark)',w:2.5});
     P.dot(1,5,{r:6,c:'var(--ink)',l:'t = 1'}).dot(1+v.h,s(1+v.h),{r:5,c:'var(--spark)'}); return P.svg(); },
   info:v=>`Vitesse moyenne entre 1 et ${fmt(1+v.h)} : (${fmt(5*(1+v.h)**2)} − 5)/${fmt(v.h)} = ${fmt(10+5*v.h)} m/s. Vitesse instantanée : 10 m/s.`},
  {h:'Taux d’accroissement et sécantes',p:`<p>Fixons une fonction f, un point <i>a</i> et un petit déplacement <i>h</i> ≠ 0.</p>`
   +DEF(`Le <b>taux d’accroissement</b> de f entre <i>a</i> et <i>a</i> + <i>h</i> est <b>τ(<i>h</i>) = ${F('f(<i>a</i> + <i>h</i>) − f(<i>a</i>)','<i>h</i>')}</b>. C’est la <b>pente de la sécante</b>, la droite qui joint les points A(<i>a</i> ; f(<i>a</i>)) et M(<i>a</i> + <i>h</i> ; f(<i>a</i> + <i>h</i>)) de la courbe.`)
   +WHY(`La pente d’une droite passant par deux points est « montée sur avancée » : (différence des ordonnées)/(différence des abscisses) = (f(<i>a</i> + <i>h</i>) − f(<i>a</i>))/((<i>a</i> + <i>h</i>) − <i>a</i>). Le dénominateur est bien <i>h</i>.`)
   +EX(`Pour f(<i>x</i>) = <i>x</i>²/2 : τ(<i>h</i>) = ${F('(<i>a</i> + <i>h</i>)²/2 − <i>a</i>²/2','<i>h</i>')} = ${F('2<i>ah</i> + <i>h</i>²','2<i>h</i>')} = <i>a</i> + <i>h</i>/2. Le facteur <i>h</i> du numérateur s’est simplifié : le taux a une expression valable pour tout <i>h</i> ≠ 0, et elle a une limite évidente quand <i>h</i> → 0, qui est <i>a</i>.`)
   +IDEA(`Déplace <i>a</i> et <i>h</i>. Quand <i>h</i> diminue, M glisse vers A et la sécante tourne autour de A. Un <i>h</i> négatif met M à gauche de A : le taux a la même formule et la même limite. Le taux lui-même n’est jamais défini en <i>h</i> = 0, mais sa limite, elle, a un sens.`),
   params:[{id:'a',l:'Abscisse a',min:-2,max:2,step:.5,v:1},{id:'h',l:'Déplacement h',min:-2,max:2,step:.25,v:1.5}],
   draw:v=>{ const f=t=>t*t/2, P=plane({x:[-4,4],y:[-1.5,6],h:280,lab:1}); P.fn(f); P.fn(t=>f(v.a)+v.a*(t-v.a),{c:'var(--ok)',w:2,dash:true});
     if(v.h!==0) P.fn(t=>f(v.a)+(v.a+v.h/2)*(t-v.a),{c:'var(--spark)',w:2.5}).dot(v.a+v.h,f(v.a+v.h),{r:5,c:'var(--spark)',l:'M'});
     P.dot(v.a,f(v.a),{r:6,c:'var(--ink)',l:'A'}); return P.svg(); },
   info:v=>v.h===0?`h = 0 : le taux n’est pas défini (0/0). Sa limite vaut a = ${fmt(v.a)} : pente de la tangente en pointillé.`:`τ(h) = a + h/2 = ${fmt(v.a+v.h/2)} (pente de la sécante). Limite quand h → 0 : a = ${fmt(v.a)}.`},
  {h:'Le nombre dérivé',p:`<p>La position limite des sécantes se traduit par une limite de nombres : celle du taux d’accroissement.</p>`
   +DEF(`f est <b>dérivable en <i>a</i></b> si le taux d’accroissement a une limite <b>finie</b> quand <i>h</i> → 0. Cette limite est le <b>nombre dérivé</b> de f en <i>a</i>, noté f′(<i>a</i>) (lire « f prime de <i>a</i> ») : <b>f′(<i>a</i>) = ${L(0,'h')} ${F('f(<i>a</i> + <i>h</i>) − f(<i>a</i>)','<i>h</i>')}</b>. En posant <i>x</i> = <i>a</i> + <i>h</i>, on a aussi f′(<i>a</i>) = ${L('<i>a</i>')} ${F('f(<i>x</i>) − f(<i>a</i>)','<i>x</i> − <i>a</i>')}.`)
   +IDEA(`f′(<i>a</i>) mesure la <b>vitesse de variation</b> de f en <i>a</i> : de combien f augmente, par unité de <i>x</i>, quand on bouge à peine. En physique, c’est une vitesse (dérivée de la position) ; sur une courbe, c’est la pente qu’on voit en zoomant sur le point. Si la limite est infinie ou n’existe pas, f n’est pas dérivable en <i>a</i>.`)
   +EX(`f(<i>x</i>) = <i>x</i>², en <i>a</i> quelconque : τ(<i>h</i>) = ${F('(<i>a</i> + <i>h</i>)² − <i>a</i>²','<i>h</i>')} = ${F('2<i>ah</i> + <i>h</i>²','<i>h</i>')} = 2<i>a</i> + <i>h</i> → 2<i>a</i>. Donc <b>f′(<i>a</i>) = 2<i>a</i></b> : f′(3) = 6, f′(0) = 0, f′(−1) = −2. Une fonction constante a un taux nul, donc une dérivée nulle ; une fonction affine <i>mx</i> + <i>p</i> a un taux constant égal à <i>m</i>, donc f′(<i>a</i>) = <i>m</i>.`)
   +WARN(`Le taux est toujours une forme 0/0 en <i>h</i> = 0 (si f est continue). Remplacer <i>h</i> par 0 avant d’avoir simplifié ne donne rien : il faut d’abord faire apparaître et simplifier le facteur <i>h</i>.`)},
  {h:'Par la définition',p:'Soit f(<i>x</i>) = <i>x</i>² − 3<i>x</i>. Calcule f′(2) à partir du taux d’accroissement.',lab:'f′(2) =',ans:1,
   why:'f(2 + h) − f(2) = (4 + 4h + h²) − (6 + 3h) − (4 − 6) = h + h². Le taux vaut 1 + h, qui tend vers 1.'},
  {h:'La tangente',p:`<p>La sécante a une position limite quand M se rapproche de A : une droite qui passe par A avec la pente f′(<i>a</i>).</p>`
   +DEF(`Si f est dérivable en <i>a</i>, la <b>tangente</b> à la courbe de f au point A(<i>a</i> ; f(<i>a</i>)) est la droite d’équation <b><i>y</i> = f(<i>a</i>) + f′(<i>a</i>)(<i>x</i> − <i>a</i>)</b>.`)
   +WHY(`Une droite de pente <i>m</i> qui passe par (<i>a</i> ; <i>b</i>) a pour équation <i>y</i> − <i>b</i> = <i>m</i>(<i>x</i> − <i>a</i>) : pour tout point (<i>x</i> ; <i>y</i>) de la droite, « montée sur avancée » vaut <i>m</i>. On applique avec <i>b</i> = f(<i>a</i>) et <i>m</i> = f′(<i>a</i>).`)
   +EX(`f(<i>x</i>) = <i>x</i>², <i>a</i> = 1 : f(1) = 1 et f′(1) = 2, donc la tangente est <i>y</i> = 1 + 2(<i>x</i> − 1) = <b>2<i>x</i> − 1</b>. Elle touche la parabole en (1 ; 1) et passe par (0 ; −1) et (1/2 ; 0).`)
   +IDEA(`Parmi toutes les droites qui passent par A, la tangente est celle qui <b>colle le mieux</b> à la courbe près de A : l’écart entre la courbe et la tangente devient négligeable devant |<i>x</i> − <i>a</i>|, alors que pour toute autre droite il reste proportionnel à |<i>x</i> − <i>a</i>|. C’est l’idée de l’approximation affine, en fin de chapitre.`)
   +WARN(`« Toucher sans traverser » n’est pas la définition. La tangente à <i>y</i> = <i>x</i>³ en 0 est l’axe des <i>x</i> (f′(0) = 0), et la courbe la traverse. Une tangente horizontale signale f′(<i>a</i>) = 0, pas forcément un sommet.`),
   fig:(()=>{ const P=plane({x:[-2.5,3],y:[-2,6],h:280,lab:1}); P.fn(t=>t*t).fn(t=>2*t-1,{c:'var(--ok)',w:2}); P.dot(1,1,{r:6,c:'var(--ink)',l:'A(1 ; 1)'}).dot(0,-1,{r:4,c:'var(--ok)'}).dot(.5,0,{r:4,c:'var(--ok)'}).text(2.3,4.2,'y = 2x − 1',{c:'var(--ok)',a:'end'}); return P.svg(); })()},
  {kind:'Méthode',h:'Écrire l’équation de la tangente',
   p:'<b>Quand :</b> on demande la tangente à la courbe de f au point d’abscisse <i>a</i>, ou la droite qui approche le mieux la courbe en ce point. <b>Pourquoi ça marche :</b> une droite est déterminée par un point et une pente ; le point est A(<i>a</i> ; f(<i>a</i>)) et la pente est f′(<i>a</i>). <b>Comment :</b><ol><li>calcule f(<i>a</i>) : l’ordonnée du point de contact ;</li><li>calcule f′(<i>a</i>) (ici par la définition : écris le taux, simplifie par <i>h</i>, passe à la limite) ;</li><li>écris <i>y</i> = f(<i>a</i>) + f′(<i>a</i>)(<i>x</i> − <i>a</i>) et développe sous la forme <i>y</i> = <i>mx</i> + <i>p</i> ;</li><li>contrôle : le point A doit vérifier l’équation.</li></ol>',
   demo:{enonce:'Tangente à la courbe de f(<i>x</i>) = <i>x</i>² − <i>x</i> au point d’abscisse 2.',
    etapes:[{f:'f(2) = 4 − 2 = 2 : le point de contact est A(2 ; 2).',w:'L’ordonnée du point.'},
     {f:`τ(<i>h</i>) = ${F('(2 + <i>h</i>)² − (2 + <i>h</i>) − 2','<i>h</i>')} = ${F('3<i>h</i> + <i>h</i>²','<i>h</i>')} = 3 + <i>h</i> → 3, donc f′(2) = 3`,w:'Le taux d’accroissement, simplifié par h, puis sa limite.'},
     {f:'<i>y</i> = 2 + 3(<i>x</i> − 2) = 3<i>x</i> − 4',w:'La formule de la tangente, développée.'},
     {f:'Contrôle : 3 · 2 − 4 = 2 = f(2).',w:'A est bien sur la droite.'}],
    conclusion:'La tangente en 2 est <i>y</i> = 3<i>x</i> − 4.'}},
  {h:'Où la tangente coupe l’axe',p:'Soit f(<i>x</i>) = <i>x</i>². Quelle est l’ordonnée à l’origine de la tangente à sa courbe au point d’abscisse −1 ?',lab:'p =',ans:-1,
   why:'f(−1) = 1 et f′(−1) = 2 · (−1) = −2. Tangente : y = 1 − 2(x + 1) = −2x − 1. Elle coupe l’axe des y en −1.'},
  {h:'Dérivable implique continue, pas l’inverse',p:`<p>Être dérivable est une exigence plus forte qu’être continue : la courbe doit non seulement ne pas sauter, mais aussi avoir une pente bien définie.</p>`
   +THM(`Si f est dérivable en <i>a</i>, alors f est <b>continue</b> en <i>a</i>.`)
   +WHY(`Pour <i>h</i> ≠ 0, f(<i>a</i> + <i>h</i>) − f(<i>a</i>) = <i>h</i> · τ(<i>h</i>). Quand <i>h</i> → 0, <i>h</i> → 0 et τ(<i>h</i>) → f′(<i>a</i>) (un nombre fini) : le produit tend vers 0 · f′(<i>a</i>) = 0. Donc f(<i>a</i> + <i>h</i>) → f(<i>a</i>), ce qui est la continuité en <i>a</i>. Le point clé est que la limite du taux est <b>finie</b>.`)
   +WARN(`<b>La réciproque est fausse.</b> f(<i>x</i>) = |<i>x</i>| est continue en 0, mais τ(<i>h</i>) = |<i>h</i>|/<i>h</i> vaut 1 pour <i>h</i> &gt; 0 et −1 pour <i>h</i> &lt; 0 : les limites à gauche et à droite diffèrent, le taux n’a pas de limite, f n’est pas dérivable en 0. Le graphe a un <b>angle</b> en 0 (figure).`)
   +EX(`Contraposée utile : une fonction <b>non continue</b> en <i>a</i> n’y est jamais dérivable. Inutile de calculer un taux pour la partie entière en 1, elle saute.`)
   +IDEA(`Dérivable, c’est « lisse » : en zoomant assez sur le point, la courbe ressemble à une droite. Sur |<i>x</i>| en 0, on a beau zoomer, l’angle reste un angle.`),
   fig:(()=>{ const P=plane({x:[-3,3],y:[-1,3],h:220,lab:1}); P.fn(Math.abs).seg(0,0,2.8,2.8,{c:'var(--spark)',w:2,dash:true}).seg(0,0,-2.8,2.8,{c:'var(--math)',w:2,dash:true}).text(1.8,1.1,'pente 1',{c:'var(--spark)'}).text(-2.9,1.1,'pente −1',{c:'var(--math)'}).dot(0,0,{r:5,c:'var(--ink)'}); return P.svg(); })()},
  {h:'Dérivées à gauche et à droite, points anguleux',p:`<p>Quand le taux n’a pas de limite, il a parfois une limite de chaque côté. Ici f(<i>x</i>) = |<i>x</i>² − 1| au point <i>a</i> = 1.</p>`
   +DEF(`Le <b>nombre dérivé à droite</b> est f′<sub>d</sub>(<i>a</i>) = ${L('0⁺','h')} τ(<i>h</i>), le <b>nombre dérivé à gauche</b> f′<sub>g</sub>(<i>a</i>) = ${L('0⁻','h')} τ(<i>h</i>), quand ces limites existent et sont finies.`)
   +PROP(`f est dérivable en <i>a</i> si et seulement si f′<sub>g</sub>(<i>a</i>) et f′<sub>d</sub>(<i>a</i>) existent <b>et sont égales</b>. Si elles existent mais diffèrent, A est un <b>point anguleux</b> : la courbe y a deux <b>demi-tangentes</b> de pentes différentes.`)
   +WHY(`C’est le critère des limites latérales appliqué à la fonction <i>h</i> ↦ τ(<i>h</i>) : une limite en 0 existe si et seulement si les limites à gauche et à droite existent et coïncident.`)
   +EX(`Pour <i>h</i> &gt; 0 petit, (1 + <i>h</i>)² − 1 = 2<i>h</i> + <i>h</i>² &gt; 0, donc τ(<i>h</i>) = (2<i>h</i> + <i>h</i>²)/<i>h</i> = 2 + <i>h</i> → <b>2</b>. Pour <i>h</i> &lt; 0 petit, la quantité est négative, la valeur absolue change le signe : τ(<i>h</i>) = −(2 + <i>h</i>) → <b>−2</b>. f′<sub>d</sub>(1) = 2 ≠ f′<sub>g</sub>(1) = −2 : point anguleux en 1. Fais passer <i>h</i> d’un côté à l’autre.`)
   +WARN(`Autre façon de ne pas être dérivable : un taux qui tend vers ±∞. Pour √<i>x</i> en 0, τ(<i>h</i>) = √<i>h</i>/<i>h</i> = 1/√<i>h</i> → +∞ : la courbe a une <b>tangente verticale</b>, mais pas de nombre dérivé.`),
   params:[{id:'h',l:'Déplacement h',min:-1,max:1,step:.1,v:.6}],
   draw:v=>{ const f=t=>Math.abs(t*t-1), P=plane({x:[-1.5,2.5],y:[-.6,3],h:270,lab:1}); P.fn(f,{from:-1.5,to:1}).fn(f,{from:1,to:2.5});
     P.fn(t=>2*(t-1),{from:1,to:2.5,c:'var(--spark)',w:2,dash:true}).fn(t=>-2*(t-1),{from:-1.5,to:1,c:'var(--math)',w:2,dash:true});
     if(Math.abs(v.h)>1e-9){ const m=(f(1+v.h)-f(1))/v.h; P.fn(t=>m*(t-1),{c:v.h>0?'var(--spark)':'var(--math)',w:2.5}).dot(1+v.h,f(1+v.h),{r:5,c:v.h>0?'var(--spark)':'var(--math)',l:'M'}); }
     P.dot(1,0,{r:6,c:'var(--ink)',l:'A'}); return P.svg(); },
   info:v=>Math.abs(v.h)<1e-9?'h = 0 : taux non défini. Demi-tangentes : pente 2 à droite, pente −2 à gauche.':`τ(${fmt(v.h)}) = ${fmt((Math.abs((1+v.h)**2-1))/v.h,3)} → ${v.h>0?'2 (à droite)':'−2 (à gauche)'}.`},
  {h:'Anguleux ou pas ?',p:'Soit f(<i>x</i>) = <i>x</i> · |<i>x</i>|, qui vaut <i>x</i>² pour <i>x</i> ≥ 0 et −<i>x</i>² pour <i>x</i> &lt; 0. Est-elle dérivable en 0 ?',
   opts:['Non : point anguleux, pentes 1 et −1','Oui, et f′(0) = 0','Oui, et f′(0) = 1','Non, car |<i>x</i>| n’est pas dérivable en 0'],ans:1,
   why:'τ(h) = h|h|/h = |h|, qui tend vers 0 des deux côtés. Les dérivées à gauche et à droite valent toutes deux 0 : f est dérivable en 0 et f′(0) = 0. Un produit contenant |x| peut très bien être dérivable.'},
  {h:'La fonction dérivée',p:`<p>Dans l’exemple de <i>x</i>², le nombre dérivé 2<i>a</i> dépend de <i>a</i>. En faisant varier le point, on obtient une nouvelle fonction.</p>`
   +DEF(`Si f est dérivable en tout point d’un intervalle <i>I</i>, la <b>fonction dérivée</b> de f est <b>f′ : <i>I</i> → ℝ, <i>x</i> ↦ f′(<i>x</i>)</b>. On dit que f est <b>dérivable sur <i>I</i></b>. On note aussi f′ = ${F('d<i>f</i>','d<i>x</i>')}, notation qui rappelle le quotient de deux petits accroissements.`)
   +EX(`(<i>x</i>²)′ = 2<i>x</i> sur ℝ. (<i>c</i>)′ = 0 pour une constante. (<i>mx</i> + <i>p</i>)′ = <i>m</i> : la dérivée d’une fonction affine est sa pente, en particulier (<i>x</i>)′ = 1. Et |<i>x</i>| est dérivable sur ]0 ; +∞[ (dérivée 1) et sur ]−∞ ; 0[ (dérivée −1), mais pas sur ℝ.`)
   +IDEA(`f′ est une fonction à part entière, avec son propre graphe. Là où f monte, les tangentes ont une pente positive et f′ &gt; 0 ; là où f descend, f′ &lt; 0 ; aux sommets, la tangente est horizontale et f′ = 0. Pour <i>x</i>², la dérivée 2<i>x</i> est négative à gauche de 0, nulle en 0, positive à droite : exactement les variations de la parabole. Le lien précis entre signe de f′ et sens de variation est l’objet du chapitre suivant.`)
   +WARN(`f′(<i>a</i>) est un nombre, f′ est une fonction. « La dérivée vaut 2<i>x</i> » parle de la fonction ; « la dérivée en 3 vaut 6 » parle du nombre f′(3).`)},
  {kind:'Méthode',h:'Dériver avec la définition',
   p:'<b>Quand :</b> on demande f′(<i>a</i>) ou f′(<i>x</i>) « par la définition », ou on ne connaît aucune règle pour f. <b>Pourquoi ça marche :</b> le taux est une forme 0/0 ; toute la technique consiste à <b>faire apparaître un facteur <i>h</i></b> au numérateur pour le simplifier avec le dénominateur. Trois situations reviennent sans cesse :<ul><li><b>puissances</b> : on développe (<i>a</i> + <i>h</i>)<sup><i>n</i></sup>, tous les termes sauf <i>a</i><sup><i>n</i></sup> contiennent <i>h</i> ;</li><li><b>quotients</b> comme 1/<i>x</i> : on met au même dénominateur, le numérateur devient un multiple de <i>h</i> ;</li><li><b>racines</b> : on multiplie par la quantité conjuguée.</li></ul><b>Comment :</b> écris f(<i>a</i> + <i>h</i>) − f(<i>a</i>), transforme jusqu’à voir <i>h</i> en facteur, divise par <i>h</i>, puis fais <i>h</i> → 0.',
   demo:{enonce:'Calculer la dérivée de f(<i>x</i>) = 1/<i>x</i> en un point <i>a</i> ≠ 0.',
    etapes:[{f:`f(<i>a</i> + <i>h</i>) − f(<i>a</i>) = ${F('1','<i>a</i> + <i>h</i>')} − ${F('1','<i>a</i>')} = ${F('<i>a</i> − (<i>a</i> + <i>h</i>)','<i>a</i>(<i>a</i> + <i>h</i>)')} = ${F('−<i>h</i>','<i>a</i>(<i>a</i> + <i>h</i>)')}`,w:'Même dénominateur : le facteur h apparaît au numérateur.'},
     {f:`τ(<i>h</i>) = ${F('−<i>h</i>','<i>h</i> · <i>a</i>(<i>a</i> + <i>h</i>)')} = ${F('−1','<i>a</i>(<i>a</i> + <i>h</i>)')}`,w:'On divise par h ≠ 0 et on simplifie.'},
     {f:`${L(0,'h')} τ(<i>h</i>) = ${F('−1','<i>a</i> · <i>a</i>')} = −${F('1','<i>a</i>²')}`,w:'Plus de 0/0 : on remplace h par 0 (la fonction obtenue est continue en 0).'}],
    conclusion:'f′(<i>a</i>) = −1/<i>a</i>² pour tout <i>a</i> ≠ 0 : <b>(1/<i>x</i>)′ = −1/<i>x</i>²</b>. La dérivée est toujours négative : 1/<i>x</i> décroît sur chaque moitié de son domaine.'},
   note:'Rappels utiles : (a + h)² = a² + 2ah + h², (a + h)³ = a³ + 3a²h + 3ah² + h³, et (√u − √v)(√u + √v) = u − v.'},
  {h:'Les dérivées de référence : √x et xⁿ',p:`<p>La méthode précédente, appliquée une fois pour toutes, donne les dérivées des fonctions de base.</p>`
   +PROP(`<ul><li><b>(√<i>x</i>)′ = ${F('1','2√<i>x</i>')}</b> pour <i>x</i> &gt; 0 ;</li><li><b>(<i>x</i><sup><i>n</i></sup>)′ = <i>n</i><i>x</i><sup><i>n</i>−1</sup></b> pour <i>n</i> ∈ ℕ* ;</li><li>(1/<i>x</i>)′ = −1/<i>x</i>², ce qui est la formule <i>nx</i><sup><i>n</i>−1</sup> avec <i>n</i> = −1.</li></ul>`)
   +WHY(`<b>Racine</b> : τ(<i>h</i>) = ${F('√(<i>a</i> + <i>h</i>) − √<i>a</i>','<i>h</i>')} = ${F('(<i>a</i> + <i>h</i>) − <i>a</i>','<i>h</i>(√(<i>a</i> + <i>h</i>) + √<i>a</i>)')} = ${F('1','√(<i>a</i> + <i>h</i>) + √<i>a</i>')} → ${F('1','2√<i>a</i>')}, par la quantité conjuguée. <b>Puissance</b>, par factorisation : <i>x</i><sup><i>n</i></sup> − <i>a</i><sup><i>n</i></sup> = (<i>x</i> − <i>a</i>)(<i>x</i><sup><i>n</i>−1</sup> + <i>x</i><sup><i>n</i>−2</sup><i>a</i> + … + <i>a</i><sup><i>n</i>−1</sup>), donc ${F('<i>x</i><sup><i>n</i></sup> − <i>a</i><sup><i>n</i></sup>','<i>x</i> − <i>a</i>')} est une somme de <i>n</i> termes qui tendent chacun vers <i>a</i><sup><i>n</i>−1</sup> quand <i>x</i> → <i>a</i> : la limite est <i>n</i><i>a</i><sup><i>n</i>−1</sup>. On peut aussi développer (<i>a</i> + <i>h</i>)<sup><i>n</i></sup> avec le binôme : <i>a</i><sup><i>n</i></sup> + <i>n</i><i>a</i><sup><i>n</i>−1</sup><i>h</i> + <i>h</i>² · (…), et le terme en <i>h</i> donne la dérivée.`)
   +EX(`(<i>x</i>⁵)′ = 5<i>x</i>⁴ ; pour f(<i>x</i>) = <i>x</i>³, f′(2) = 3 · 2² = 12 ; pour f(<i>x</i>) = √<i>x</i>, f′(9) = 1/(2 · 3) = 1/6, et la tangente en 9 est <i>y</i> = 3 + (<i>x</i> − 9)/6.`)
   +WARN(`√<i>x</i> est définie en 0 mais pas dérivable en 0 (tangente verticale) : la formule 1/(2√<i>x</i>) n’y a pas de sens. Une fonction peut être définie en un point sans y être dérivable.`)},
  {h:'Une puissance en un point',p:'Soit f(<i>x</i>) = <i>x</i>⁴. Calcule f′(−1).',lab:'f′(−1) =',ans:-4,
   why:'f′(x) = 4x³, donc f′(−1) = 4 · (−1)³ = −4. La tangente en (−1 ; 1) descend : la courbe de x⁴ décroît à gauche de 0.'},
  {h:'L’approximation affine',p:`<p>Près de A, la courbe et sa tangente sont presque confondues. On peut donc remplacer f par la tangente pour <b>estimer</b> une valeur difficile à calculer.</p>`
   +PROP(`Si f est dérivable en <i>a</i>, alors pour <i>h</i> petit : <b>f(<i>a</i> + <i>h</i>) ≈ f(<i>a</i>) + f′(<i>a</i>) · <i>h</i></b>. Plus précisément, f(<i>a</i> + <i>h</i>) = f(<i>a</i>) + f′(<i>a</i>)<i>h</i> + <i>h</i> · ε(<i>h</i>) avec ε(<i>h</i>) → 0 quand <i>h</i> → 0.`)
   +WHY(`Posons ε(<i>h</i>) = τ(<i>h</i>) − f′(<i>a</i>). Par définition de la dérivée, ε(<i>h</i>) → 0. Et τ(<i>h</i>) = f′(<i>a</i>) + ε(<i>h</i>) se réécrit f(<i>a</i> + <i>h</i>) − f(<i>a</i>) = f′(<i>a</i>)<i>h</i> + <i>h</i>ε(<i>h</i>). L’erreur <i>h</i>ε(<i>h</i>) est un « petit multiplié par un petit » : elle devient négligeable devant le terme principal f′(<i>a</i>)<i>h</i>.`)
   +EX(`√16,1 : on prend f(<i>x</i>) = √<i>x</i>, <i>a</i> = 16, <i>h</i> = 0,1. f(16) = 4 et f′(16) = 1/(2 · 4) = 1/8. Donc √16,1 ≈ 4 + 0,1/8 = <b>4,0125</b>. La valeur exacte est 4,01248… : l’erreur est inférieure à 0,00002.`)
   +IDEA(`Sur la figure, f(<i>x</i>) = √<i>x</i> et <i>a</i> = 4 : le point de la tangente (vert) et le point de la courbe (orange) de même abscisse 4 + <i>h</i>. Réduis <i>h</i> : l’écart entre les deux fond bien plus vite que <i>h</i>. Divise <i>h</i> par 2, l’erreur est divisée par environ 4.`),
   params:[{id:'h',l:'Déplacement h',min:.1,max:4,step:.1,v:4}],
   draw:v=>{ const f=Math.sqrt, P=plane({x:[-.5,9.5],y:[-.5,3.6],h:220,lab:2}); P.fn(f,{from:0,to:9.5}).fn(t=>2+(t-4)/4,{c:'var(--ok)',w:2,dash:true}); P.seg(4+v.h,f(4+v.h),4+v.h,2+v.h/4,{c:'var(--bad)',w:3});
     P.dot(4,2,{r:6,c:'var(--ink)',l:'A'}).dot(4+v.h,2+v.h/4,{r:5,c:'var(--ok)'}).dot(4+v.h,f(4+v.h),{r:5,c:'var(--spark)'}); return P.svg(); },
   info:v=>`√(4 + ${fmt(v.h)}) ≈ 2 + ${fmt(v.h)}/4 = ${fmt(2+v.h/4,4)} ; valeur exacte ${fmt(Math.sqrt(4+v.h),4)} ; erreur ${fmt(2+v.h/4-Math.sqrt(4+v.h),4)}.`},
  {kind:'Méthode',h:'Estimer une valeur avec la tangente',
   p:'<b>Quand :</b> on veut une valeur approchée de f(<i>b</i>) sans calculatrice, et <i>b</i> est proche d’un nombre <i>a</i> où f et f′ se calculent facilement (carré parfait pour une racine, entier pour une puissance). <b>Pourquoi ça marche :</b> l’approximation affine f(<i>a</i> + <i>h</i>) ≈ f(<i>a</i>) + f′(<i>a</i>)<i>h</i>, dont l’erreur est négligeable devant <i>h</i>. <b>Comment :</b><ol><li>choisis f, le point commode <i>a</i> et <i>h</i> = <i>b</i> − <i>a</i> (petit, éventuellement négatif) ;</li><li>calcule f(<i>a</i>) et f′(<i>a</i>) ;</li><li>calcule f(<i>a</i>) + f′(<i>a</i>)<i>h</i> ;</li><li>situe l’erreur : si la courbe est au-dessus de sa tangente (comme <i>x</i>³ pour <i>x</i> &gt; 0), l’estimation est par défaut ; si elle est en dessous (comme √<i>x</i>), par excès.</li></ol>',
   demo:{enonce:'Estimer 2,01³ sans calculatrice.',
    etapes:[{f:'f(<i>x</i>) = <i>x</i>³, <i>a</i> = 2, <i>h</i> = 0,01',w:'2 est un point où le cube et sa dérivée sont immédiats.'},
     {f:'f(2) = 8 et f′(<i>x</i>) = 3<i>x</i>², donc f′(2) = 12',w:'Valeur et pente au point commode.'},
     {f:'2,01³ ≈ 8 + 12 · 0,01 = 8,12',w:'L’approximation affine.'},
     {f:'Valeur exacte : 8,120601. Erreur 0,0006, soit 6 · 0,01² : bien plus petite que <i>h</i>.',w:'L’erreur est de l’ordre de h², comme annoncé.'}],
    conclusion:'2,01³ ≈ 8,12, par défaut (la courbe de <i>x</i>³ est au-dessus de sa tangente pour <i>x</i> &gt; 0).'},
   note:'Même idée en physique : pour une petite variation de la variable, la variation de la grandeur est à peu près f′(a) fois la variation de la variable. f′(a) est un « taux de conversion » local.'},
  {h:'Une racine sans calculatrice',p:'Estime √25,2 avec l’approximation affine en <i>a</i> = 25. Donne le résultat de la formule (sans arrondir).',lab:'√25,2 ≈',ans:5.02,tol:1e-6,
   why:'f(x) = √x, f(25) = 5, f′(25) = 1/(2 · 5) = 1/10, h = 0,2. Donc √25,2 ≈ 5 + 0,2/10 = 5,02. La valeur exacte est 5,01996… : l’estimation est par excès, de 0,00004.'},
  {kind:'Récapitulatif',h:'Ce qu’il faut retenir',p:`<p>La dérivée est une limite : tout le chapitre découle de cette phrase.</p>`
   +KEEP(`<ul><li><b>Taux d’accroissement</b> τ(<i>h</i>) = (f(<i>a</i> + <i>h</i>) − f(<i>a</i>))/<i>h</i> : pente de la sécante, vitesse moyenne.</li><li><b>Nombre dérivé</b> f′(<i>a</i>) = lim<sub>h→0</sub> τ(<i>h</i>) (limite finie) : pente de la tangente, vitesse instantanée.</li><li><b>Tangente</b> en <i>a</i> : <i>y</i> = f(<i>a</i>) + f′(<i>a</i>)(<i>x</i> − <i>a</i>).</li><li><b>Dérivable ⇒ continue</b> (car f(<i>a</i> + <i>h</i>) − f(<i>a</i>) = <i>h</i>τ(<i>h</i>) → 0). Réciproque fausse : |<i>x</i>| en 0.</li><li><b>Dérivées latérales</b> : dérivable ⇔ f′<sub>g</sub> = f′<sub>d</sub>. Sinon point anguleux (|<i>x</i>|) ou tangente verticale (√<i>x</i> en 0).</li><li><b>Fonction dérivée</b> f′ : <i>x</i> ↦ f′(<i>x</i>).</li><li><b>Par la définition</b> : faire apparaître <i>h</i> en facteur (développer, même dénominateur, conjugué).</li><li><b>Références</b> : (<i>c</i>)′ = 0, (<i>mx</i> + <i>p</i>)′ = <i>m</i>, (<i>x</i><sup><i>n</i></sup>)′ = <i>nx</i><sup><i>n</i>−1</sup>, (1/<i>x</i>)′ = −1/<i>x</i>², (√<i>x</i>)′ = 1/(2√<i>x</i>).</li><li><b>Approximation affine</b> : f(<i>a</i> + <i>h</i>) ≈ f(<i>a</i>) + f′(<i>a</i>)<i>h</i>, erreur négligeable devant <i>h</i>.</li></ul>`)},
  {kind:'Problème',h:'La chute d’une bille',
   p:'Une bille est lâchée du haut d’un mur de 20 m. Sa hauteur au-dessus du sol après <i>t</i> secondes est <i>y</i>(<i>t</i>) = 20 − 5<i>t</i>² (en mètres), tant qu’elle n’a pas touché le sol. On veut comparer vitesse moyenne et vitesse instantanée, puis connaître la vitesse d’impact. Une vitesse négative signifie que la hauteur diminue.',
   fig:(()=>{ const P=plane({x:[-.3,2.6],y:[-3,22],h:240,step:5,lx:1,ly:5}); P.fn(t=>20-5*t*t,{from:0,to:2}).seg(1,15,2,0,{c:'var(--spark)',w:2,dash:true}).fn(t=>15-10*(t-1),{from:.3,to:2.2,c:'var(--ok)',w:2}); P.dot(1,15,{r:5,c:'var(--ink)',l:'t = 1'}).dot(2,0,{r:5,c:'var(--ink)',l:'sol',dy:-10}); return P.svg(); })(),
   parts:[
    {q:'a) Quelle est la vitesse moyenne de la bille entre <i>t</i> = 1 et <i>t</i> = 2 ?',lab:'v =',unit:'m/s',ans:-15,hint:'Taux d’accroissement de y entre 1 et 2 : (y(2) − y(1))/(2 − 1).',why:'y(1) = 15 et y(2) = 0. Vitesse moyenne : (0 − 15)/1 = −15 m/s (pente de la sécante en pointillé).'},
    {q:'b) Calcule la vitesse instantanée <i>y</i>′(1) à partir du taux d’accroissement.',lab:'y′(1) =',unit:'m/s',ans:-10,hint:'y(1 + h) − y(1) = 20 − 5(1 + h)² − 15. Développe, simplifie par h.',why:'y(1 + h) − y(1) = 5 − 5(1 + 2h + h²) = −10h − 5h². Le taux vaut −10 − 5h → −10. La bille descend à 10 m/s à l’instant 1.'},
    {q:'c) À quel instant la bille touche-t-elle le sol ?',lab:'t =',unit:'s',ans:2,hint:'Résous y(t) = 0 avec t > 0.',why:'20 − 5t² = 0 ⇔ t² = 4 ⇔ t = 2 (t > 0).'},
    {q:'d) Quelle est sa vitesse à l’impact ?',lab:'y′(2) =',unit:'m/s',ans:-20,hint:'Dérivée de 20 − 5t² : utilise (t²)′ = 2t et les constantes.',why:'y′(t) = −5 · 2t = −10t, donc y′(2) = −20 m/s, soit 72 km/h. La vitesse moyenne −15 m/s sur [1 ; 2] est bien comprise entre les vitesses instantanées −10 et −20.'},
   ],
   sol:'Vitesse moyenne sur [1 ; 2] : (y(2) − y(1))/1 = −15 m/s, pente de la sécante. Vitesse instantanée en 1 : le taux (y(1 + h) − y(1))/h = (−10h − 5h²)/h = −10 − 5h tend vers −10 m/s, pente de la tangente. Plus généralement, y′(t) = −10t : la vitesse est proportionnelle au temps écoulé, c’est la chute libre. Le sol est atteint quand 20 − 5t² = 0, soit t = 2 s, et la vitesse d’impact vaut y′(2) = −20 m/s. La vitesse moyenne −15 m/s est la moyenne des vitesses instantanées aux deux bornes, ce qui est particulier aux fonctions du second degré.'},
  {kind:'Problème',h:'Une fonction qui oscille, dérivable quand même',
   p:'On pose f(<i>x</i>) = <i>x</i>² sin(1/<i>x</i>) pour <i>x</i> ≠ 0 et f(0) = 0, puis g(<i>x</i>) = <i>x</i> sin(1/<i>x</i>) pour <i>x</i> ≠ 0 et g(0) = 0. Les deux fonctions oscillent une infinité de fois près de 0, car sin(1/<i>x</i>) n’a pas de limite en 0. On veut savoir si elles sont dérivables en 0. On rappelle que |sin <i>u</i>| ≤ 1 pour tout <i>u</i>, et le théorème des gendarmes : une fonction coincée entre deux fonctions qui tendent vers 0 tend vers 0.',
   fig:(()=>{ const P=plane({x:[-.5,.5],y:[-.3,.3],h:220,step:.1,lx:.25,ly:.1}); P.fn(t=>t*t,{c:'var(--muted)',w:1.5,dash:true}).fn(t=>-t*t,{c:'var(--muted)',w:1.5,dash:true}); P.fn(t=>t*t*Math.sin(1/t),{from:-.5,to:-.002,n:1500,w:2}).fn(t=>t*t*Math.sin(1/t),{from:.002,to:.5,n:1500,w:2}); P.dot(0,0,{r:5,c:'var(--ink)'}); return P.svg(); })(),
   parts:[
    {q:'a) Pour <i>h</i> ≠ 0, le taux d’accroissement de f en 0 vaut τ(<i>h</i>) = (f(<i>h</i>) − f(0))/<i>h</i>. Que peut-on dire de |τ(<i>h</i>)| ?',opts:['|τ(h)| ≤ |h|','|τ(h)| ≤ 1 mais pas mieux','|τ(h)| = |h|','τ(h) n’est pas défini car sin(1/h) n’a pas de limite'],ans:0,hint:'Simplifie h² sin(1/h)/h, puis majore |sin(1/h)| par 1.',why:'τ(h) = h² sin(1/h)/h = h sin(1/h), donc |τ(h)| = |h| · |sin(1/h)| ≤ |h|. L’égalité n’a lieu que si |sin(1/h)| = 1.'},
    {q:'b) Que vaut f′(0) ?',lab:'f′(0) =',ans:0,hint:'−|h| ≤ τ(h) ≤ |h| : gendarmes.',why:'τ(h) est coincé entre −|h| et |h|, qui tendent vers 0. Donc τ(h) → 0 : f est dérivable en 0 et f′(0) = 0. La tangente en 0 est l’axe des x, que la courbe traverse une infinité de fois.'},
    {q:'c) Et g en 0 ?',opts:['g est dérivable en 0, avec g′(0) = 0','g est dérivable en 0, avec g′(0) = 1','g est continue en 0 mais pas dérivable : son taux est sin(1/h), sans limite','g n’est pas continue en 0'],ans:2,hint:'Calcule le taux de g en 0, puis pense aux deux suites de la méthode « deux suites ».',why:'|g(h)| ≤ |h| → 0 = g(0) : g est continue en 0. Mais son taux vaut h sin(1/h)/h = sin(1/h), qui n’a pas de limite en 0 (les suites 1/(2πn) et 1/(π/2 + 2πn) donnent 0 et 1). g n’est pas dérivable en 0.'},
    {q:'d) Quelle est la pente de la tangente à la courbe de f au point d’abscisse 0 ?',lab:'pente =',ans:0,hint:'C’est f′(0).',why:'La pente de la tangente est f′(0) = 0 : la tangente est la droite y = 0. Entre les paraboles y = x² et y = −x² (en pointillé), la courbe est écrasée sur cette tangente.'},
   ],
   sol:'Pour f : τ(h) = (h² sin(1/h) − 0)/h = h sin(1/h), et |h sin(1/h)| ≤ |h| → 0. Par les gendarmes, τ(h) → 0 : f est dérivable en 0, f′(0) = 0, et la tangente en 0 est l’axe des abscisses. Le facteur h² est assez puissant pour écraser les oscillations. Pour g : |g(h)| ≤ |h| donne la continuité en 0, mais le taux vaut sin(1/h), qui n’a pas de limite (deux suites tendant vers 0 donnent les images 0 et 1). g est donc continue et non dérivable en 0, sans point anguleux ni tangente verticale : les sécantes oscillent sans jamais se stabiliser. Un facteur h ne suffit pas, un facteur h² suffit.'},
]},
);
})();
